const activeBusinessProfile=()=>businessProfiles[currentOrg?.business_type||currentOrg?.industry]||businessProfiles.general_erp;
const businessUsesLocations=type=>businessProfiles[type]?.locations||['salon','automotive','retail_grocery'].includes(type);
const industryOperation=()=>activeBusinessProfile().operation||null;
const industryRecordIsComplete=record=>{const operation=industryOperation();return operation&&record.status===operation.statuses.at(-1)};
const businessDepartment=()=>({clothing_fashion:'Fashion',restaurant:'Restaurant',hotel:'Hospitality',construction:'Construction',real_estate:'Property',education:'Education',healthcare_clinic:'Healthcare',logistics:'Logistics',manufacturing_business:'Production',agriculture:'Agriculture',automotive:'Automotive',retail_grocery:'Retail',pharmacy:'Pharmacy',salon:'Salon'}[currentOrg?.business_type]||'Operations');
const liveIndustryOpenWork=()=>currentOrg?.business_type==='hotel'?hotelBookings.filter(item=>!['checked_out','cancelled','no_show'].includes(item.status)).length:currentOrg?.business_type==='healthcare_clinic'?medicalQueueTickets.filter(item=>['waiting','called','in_consultation'].includes(item.status)).length:industryModuleRecords.filter(record=>!industryRecordIsComplete(record)).length;
const activeSalonServices=()=>salonServices.filter(service=>service.active!==false);
const activeSalonLocation=()=>salonLocations.find(location=>location.id===activeSalonLocationId)||null;
const locationMatches=locationId=>activeSalonLocationId==='all'||locationId===activeSalonLocationId;
const operationalProducts=()=>state.products.filter(product=>locationMatches(product.location_id));
const visibleSalonAppointments=()=>salonAppointments.filter(item=>locationMatches(item.location_id));
const visibleSalonAvailability=()=>salonAvailability.filter(item=>locationMatches(item.location_id));
const salonStaff=()=>state.employees.filter(employee=>employee.bookable&&employee.status==='Online'&&locationMatches(employee.location_id));
const employeePortalUrl=branch=>branch?.employee_login_slug?`${window.location.origin}/staff/${branch.employee_login_slug}`:'';
const isSystemAdmin=()=>userProfile?.platform_role==='system_admin';
const isSuperAdmin=()=>['super_admin','system_admin'].includes(userProfile?.platform_role);
const permissionLabels={salon_view:'View branch operations',salon_create:'Create salon bookings',salon_move:'Move salon workflow cards',salon_approve:'Confirm salon bookings',salon_allocate:'Allocate salon responsibility',hotel_view:'View hotel rooms and bookings',hotel_bookings:'Create and manage hotel bookings',hotel_manage:'Configure hotel rooms and channels',medical_view:'View medical queues',medical_issue:'Issue patient numbers',medical_call:'Call and complete patient numbers',medical_manage:'Configure doctors, staff, and sessions',customers_view:'View customers',sales_view:'View sales & income',settings_view:'View workspace settings'};
