function hasPermission(key){
 if(isSuperAdmin())return true;
 if(currentAccess?.permissions&&Object.prototype.hasOwnProperty.call(currentAccess.permissions,key))return currentAccess.permissions[key]===true;
 if(key.endsWith('_view'))return true;
 return ['owner','admin','manager'].includes(currentMembership?.role);
}

function header(title,description,primary='Create',extra='Export'){
  return `<div class="page-head"><div><span class="eyebrow">${currentOrg?.name||'Your workspace'} · ${new Date().toLocaleDateString('en-US',{month:'long',year:'numeric'})}</span><h1>${title}</h1><p>${description}</p></div><div class="head-actions"><button class="btn" data-export data-icon="download">${extra}</button><button class="btn primary" data-create data-icon="plus">${primary}</button></div></div>`;
}
function statusClass(s){return /paid|online|track|done|active|sent|completed/i.test(s)?'green':/overdue|risk|blocked|low/i.test(s)?'red':/pending|review|away|draft|progress/i.test(s)?'orange':''}

function onboardingIndustryFields(type){
 const values=onboardingDraft.preferences||{};
 const input=(label,name,value='',typeName='text',hint='')=>`<label><span>${label}</span><input data-config-field="${name}" type="${typeName}" value="${escapeHtml(value)}">${hint?`<small>${hint}</small>`:''}</label>`;
 if(type==='retail_grocery')return `<div class="onboarding-config-grid">${input('Reward every Rs.','loyalty_spend',values.loyalty_spend||100,'number','Default: Rs. 1 credit per Rs. 100 spent')}${input('Loyalty reward value','loyalty_reward',values.loyalty_reward||1,'number')}${input('Low-stock warning level','default_reorder',values.default_reorder||10,'number')}${input('Receipt prefix','receipt_prefix',values.receipt_prefix||'POS')}</div><label class="onboarding-check"><input data-config-check="change_to_loyalty" type="checkbox" ${values.change_to_loyalty!==false?'checked':''}><span><b>Allow cash change as loyalty credit</b><small>Cashiers can store unavailable change in the customer wallet.</small></span></label>`;
 if(type==='pharmacy')return `<div class="onboarding-config-grid">${input('Pharmacy licence number','pharmacy_license',values.pharmacy_license||'')}${input('Responsible pharmacist','responsible_pharmacist',values.responsible_pharmacist||'')}${input('Expiry warning days','expiry_warning_days',values.expiry_warning_days||90,'number')}${input('Prescription prefix','prescription_prefix',values.prescription_prefix||'RX')}</div><label class="onboarding-check"><input data-config-check="pharmacist_verification" type="checkbox" checked><span><b>Require verification before dispensing</b><small>Prescriptions cannot reduce stock until verified.</small></span></label>`;
 if(type==='salon')return `<div class="onboarding-config-grid">${input('Opening time','opening_time',values.opening_time||'09:00','time')}${input('Closing time','closing_time',values.closing_time||'19:00','time')}${input('Booking interval (minutes)','booking_interval',values.booking_interval||30,'number')}${input('Default commission %','commission_rate',values.commission_rate||10,'number')}</div><div class="onboarding-capacity-note">${icon('users')}<span><b>${Number(onboardingDraft.employee_count)||1} simultaneous bookings</b><small>We will create one bookable salon staff profile for each employee entered on the previous step. Staff and time off remain editable in Settings.</small></span></div><label class="onboarding-check"><input data-config-check="online_booking" type="checkbox" ${values.online_booking!==false?'checked':''}><span><b>Enable appointment-first workflow</b><small>Every service follows booking, service, checkout, and rebooking.</small></span></label>`;
 if(type==='automotive')return `<div class="onboarding-config-grid">${input('Number of service bays','service_bays',values.service_bays||3,'number')}${input('Standard labour rate / hour','labor_rate',values.labor_rate||2500,'number')}${input('Default parts markup %','parts_markup',values.parts_markup||20,'number')}${input('Job card prefix','job_prefix',values.job_prefix||'JOB')}</div><label class="onboarding-check"><input data-config-check="inspection_required" type="checkbox" checked><span><b>Require inspection and approval</b><small>Repairs cannot start before inspection and customer approval.</small></span></label>`;
 const configuration=businessProfiles[type]?.onboarding;
 if(configuration){
  const fields=configuration.fields.map(([label,name,defaultValue,typeName='text',hint=''])=>input(label,name,values[name]??defaultValue,typeName,hint)).join('');
  const [name,label,description,defaultValue]=configuration.check;const checked=(values[name]??defaultValue)!==false;
  return `<div class="onboarding-config-grid">${fields}</div><label class="onboarding-check"><input data-config-check="${name}" type="checkbox" ${checked?'checked':''}><span><b>${label}</b><small>${description}</small></span></label>`;
 }
 return `<div class="onboarding-config-grid">${input('Invoice prefix','invoice_prefix',values.invoice_prefix||'INV')}${input('Default payment terms (days)','payment_terms',values.payment_terms||30,'number')}${input('Approval threshold (Rs.)','approval_threshold',values.approval_threshold||100000,'number')}${input('Fiscal year starts','fiscal_year_start',values.fiscal_year_start||1,'number')}</div><label class="onboarding-check"><input data-config-check="management_approvals" type="checkbox" checked><span><b>Enable management approval controls</b><small>High-value transactions follow a controlled approval path.</small></span></label>`;
}

function onboardingEmployeeFields(){
 const count=Math.max(1,Number(onboardingDraft.employee_count)||1);while(onboardingDraft.employees.length<count){const index=onboardingDraft.employees.length;onboardingDraft.employees.push({employee_code:`EMP-${String(index+1).padStart(4,'0')}`,name:'',role:'',department:'Operations',email:'',phone:'',nic_passport:'',start_date:new Date().toISOString().slice(0,10),branch_index:index%Math.max(1,Number(onboardingDraft.branch_count)||1),pay_type:'monthly',base_salary:0,hourly_rate:0,standard_hours:0,allowances:0,deductions:0,payment_method:'bank',emergency_contact:'',emergency_phone:'',address:'',notes:''})}onboardingDraft.employees=onboardingDraft.employees.slice(0,count);
 const branchOptions=onboardingDraft.locations.slice(0,Math.max(1,Number(onboardingDraft.branch_count)||1)).map((branch,index)=>`<option value="${index}">${escapeHtml(branch.name||`Branch ${index+1}`)}</option>`).join('');
 return `<section class="onboarding-employees"><div class="onboarding-location-head"><span>${icon('users')}</span><div><b>Add the actual employees</b><small>Names, IDs, roles, branch assignments, and salary details are saved directly to People & Payroll.</small></div></div><div class="onboarding-employee-list">${onboardingDraft.employees.map((employee,index)=>`<article><header><div><b>Employee ${index+1}</b><small>${escapeHtml(employee.name||employee.employee_code)}</small></div><span>Required</span></header><div class="onboarding-employee-grid"><label><span>Employee ID *</span><input data-onboard-employee="employee_code" data-employee-index="${index}" value="${escapeHtml(employee.employee_code)}" required></label><label><span>Full name *</span><input data-onboard-employee="name" data-employee-index="${index}" value="${escapeHtml(employee.name)}" required></label><label><span>Role / job title *</span><input data-onboard-employee="role" data-employee-index="${index}" value="${escapeHtml(employee.role)}" placeholder="Cashier, manager, stylist" required></label><label><span>Department</span><input data-onboard-employee="department" data-employee-index="${index}" value="${escapeHtml(employee.department)}"></label><label><span>Branch *</span><select data-onboard-employee="branch_index" data-employee-index="${index}">${branchOptions}</select></label><label><span>Start date</span><input data-onboard-employee="start_date" data-employee-index="${index}" type="date" value="${escapeHtml(employee.start_date)}"></label><label><span>Work email</span><input data-onboard-employee="email" data-employee-index="${index}" type="email" value="${escapeHtml(employee.email)}"></label><label><span>Phone</span><input data-onboard-employee="phone" data-employee-index="${index}" value="${escapeHtml(employee.phone)}"></label><label><span>NIC / Passport</span><input data-onboard-employee="nic_passport" data-employee-index="${index}" value="${escapeHtml(employee.nic_passport)}"></label><label><span>Pay type</span><select data-onboard-employee="pay_type" data-employee-index="${index}"><option value="monthly">Monthly salary</option><option value="hourly">Hourly</option></select></label><label><span>Base salary (Rs.) *</span><input data-onboard-employee="base_salary" data-employee-index="${index}" type="number" min="0" step="0.01" value="${Number(employee.base_salary)||0}"></label><label><span>Fixed allowances</span><input data-onboard-employee="allowances" data-employee-index="${index}" type="number" min="0" step="0.01" value="${Number(employee.allowances)||0}"></label><label><span>Fixed deductions</span><input data-onboard-employee="deductions" data-employee-index="${index}" type="number" min="0" step="0.01" value="${Number(employee.deductions)||0}"></label><label><span>Payment method</span><select data-onboard-employee="payment_method" data-employee-index="${index}"><option value="bank">Bank transfer</option><option value="cash">Cash</option><option value="cheque">Cheque</option></select></label><label><span>Emergency contact</span><input data-onboard-employee="emergency_contact" data-employee-index="${index}" value="${escapeHtml(employee.emergency_contact)}"></label><label><span>Emergency phone</span><input data-onboard-employee="emergency_phone" data-employee-index="${index}" value="${escapeHtml(employee.emergency_phone)}"></label></div></article>`).join('')}</div></section>`;
}

function onboardingView(){
 const type=onboardingDraft.business_type;const profile=businessProfiles[type];
 const branchCount=Math.max(1,Number(onboardingDraft.branch_count)||1);while(onboardingDraft.locations.length<branchCount)onboardingDraft.locations.push({name:'',city:'',address:'',phone:''});onboardingDraft.locations=onboardingDraft.locations.slice(0,branchCount);
 const locationFields=businessUsesLocations(type)?`<section class="onboarding-locations"><div class="onboarding-location-head"><span>${icon('store')}</span><div><b>Name every business location</b><small>Branches, sites, campuses, or facilities keep employees, stock, sales, and operations separated by location.</small></div></div><div class="onboarding-location-grid">${onboardingDraft.locations.map((branch,index)=>`<article><header><b>Location ${index+1}${index===0?' · Main':''}</b><small>Permanent portal generated after activation</small></header><label><span>Location / site name *</span><input data-onboard-location="name" data-location-index="${index}" value="${escapeHtml(branch.name||'')}" placeholder="${index===0?'Colombo Main':'Negombo Branch'}" required></label><div><label><span>City</span><input data-onboard-location="city" data-location-index="${index}" value="${escapeHtml(branch.city||'')}" placeholder="${index===0?'Colombo':'Negombo'}"></label><label><span>Phone</span><input data-onboard-location="phone" data-location-index="${index}" value="${escapeHtml(branch.phone||'')}"></label></div><label><span>Location address</span><textarea data-onboard-location="address" data-location-index="${index}" rows="2">${escapeHtml(branch.address||'')}</textarea></label></article>`).join('')}</div></section>`:'';
 const steps=['Business type','Company details','Operating defaults','Review & activate'];
 const stepOne=`<div class="onboarding-heading"><span class="eyebrow">Build your workspace</span><h1>What kind of business do you run?</h1><p>Your answer activates the right operating model. You can refine it later in Settings.</p></div><div class="onboarding-business-grid">${Object.entries(businessProfiles).map(([key,item])=>`<button class="${type===key?'selected':''}" data-onboard-business="${key}"><span>${icon(item.icon)}</span><div><b>${item.label}</b><small>${item.tagline}</small><em>${item.modules.length} focused modules</em></div><i>${type===key?'✓':'→'}</i></button>`).join('')}</div>`;
 const stepTwo=`<div class="onboarding-heading"><span class="eyebrow">Company profile</span><h1>Tell us about the business</h1><p>These details appear on bills, reports, statements, and customer communication.</p></div><div class="onboarding-fields"><label><span>Trading name *</span><input data-onboard-field="company_name" value="${escapeHtml(onboardingDraft.company_name)}"></label><label><span>Legal name</span><input data-onboard-field="legal_name" value="${escapeHtml(onboardingDraft.legal_name)}"></label><label><span>Business phone</span><input data-onboard-field="phone" value="${escapeHtml(onboardingDraft.phone)}"></label><label><span>Business email</span><input data-onboard-field="email" type="email" value="${escapeHtml(onboardingDraft.email)}"></label><label><span>Registration number</span><input data-onboard-field="registration_number" value="${escapeHtml(onboardingDraft.registration_number)}"></label><label><span>Tax / VAT number</span><input data-onboard-field="tax_number" value="${escapeHtml(onboardingDraft.tax_number)}"></label><label><span>Number of branches *</span><input data-onboard-field="branch_count" type="number" min="1" max="30" value="${onboardingDraft.branch_count}"><small>Change this number to add or remove location detail cards.</small></label><label><span>Number of employees *</span><input data-onboard-field="employee_count" type="number" min="1" value="${onboardingDraft.employee_count}"></label><label class="wide"><span>Business address</span><textarea data-onboard-field="address" rows="3">${escapeHtml(onboardingDraft.address)}</textarea></label></div>${locationFields}`;
 const stepThree=`<div class="onboarding-heading"><span class="eyebrow">${profile?.label||'Business'} defaults</span><h1>Configure your daily operation</h1><p>Set operating defaults and create complete, branch-assigned employee records before activation.</p></div>${onboardingIndustryFields(type)}${onboardingEmployeeFields()}`;
 const stepFour=`<div class="onboarding-heading"><span class="eyebrow">Ready to activate</span><h1>Your workspace is ready to build</h1><p>Review the configuration. No demo app clutter will be added.</p></div><div class="onboarding-review"><div class="review-company"><span>${icon(profile?.icon||'grid')}</span><div><b>${escapeHtml(onboardingDraft.company_name)}</b><small>${profile?.label||'General Business ERP'} · ${onboardingDraft.branch_count} ${Number(onboardingDraft.branch_count)===1?'branch':'branches'} · ${onboardingDraft.employee_count} employees</small></div></div><div class="review-modules"><span>Activated modules</span>${(profile?.modules||[]).map(module=>`<b>${module.replaceAll('_',' ')}</b>`).join('')}</div><div class="review-promise"><span>${icon('check')}</span><p><b>One connected source of truth</b><small>Customers, sales, stock, employees, operations, loyalty, and finance share the same secure company workspace.</small></p></div></div>`;
 return `<div class="onboarding-shell"><header><button class="brand" aria-label="HICH ONE"><span class="brand-mark"><i></i><i></i><i></i></span><span>HICH ONE</span></button><span>Secure workspace setup</span></header><div class="onboarding-progress">${steps.map((label,index)=>`<div class="${index+1<=onboardingStep?'active':''} ${index+1<onboardingStep?'complete':''}"><i>${index+1<onboardingStep?'✓':index+1}</i><span>${label}</span></div>`).join('')}</div><main>${[stepOne,stepTwo,stepThree,stepFour][onboardingStep-1]}</main><footer>${onboardingStep>1?'<button class="btn" data-onboard-back>Back</button>':'<span></span>'}<button class="btn primary" data-onboard-next ${onboardingStep===1&&!type?'disabled':''}>${onboardingStep===4?'Activate workspace':'Continue'} ${onboardingStep<4?'→':''}</button></footer></div>`;
}

function collectOnboardingFields(){
 $$('[data-onboard-field]',page).forEach(field=>onboardingDraft[field.dataset.onboardField]=field.type==='number'?Number(field.value):field.value.trim());
 $$('[data-onboard-location]',page).forEach(field=>{const index=Number(field.dataset.locationIndex);onboardingDraft.locations[index]||={name:'',city:'',address:'',phone:''};onboardingDraft.locations[index][field.dataset.onboardLocation]=field.value.trim()});
 $$('[data-onboard-employee]',page).forEach(field=>{const index=Number(field.dataset.employeeIndex);onboardingDraft.employees[index]||={};const key=field.dataset.onboardEmployee;onboardingDraft.employees[index][key]=field.type==='number'||key==='branch_index'?Number(field.value):field.value.trim()});
 $$('[data-config-field]',page).forEach(field=>onboardingDraft.preferences[field.dataset.configField]=field.type==='number'?Number(field.value):field.value);
 $$('[data-config-check]',page).forEach(field=>onboardingDraft.preferences[field.dataset.configCheck]=field.checked);
}

function showOnboarding(){
 const existingType=businessProfiles[currentOrg?.business_type]?currentOrg.business_type:'';
 onboardingStep=1;onboardingDraft={business_type:existingType,company_name:currentOrg?.name||'',legal_name:currentOrg?.legal_name||'',phone:currentOrg?.phone||'',email:currentOrg?.email||session?.user?.email||'',address:currentOrg?.address||'',registration_number:currentOrg?.registration_number||'',tax_number:currentOrg?.tax_number||'',branch_count:currentOrg?.branch_count||salonLocations.length||1,employee_count:currentOrg?.employee_count||1,locations:salonLocations.length?salonLocations.map(branch=>({name:branch.name,city:branch.city||'',address:branch.address||'',phone:branch.phone||''})):[{name:currentOrg?.name?`${currentOrg.name} Main`:'',city:'',address:currentOrg?.address||'',phone:currentOrg?.phone||''}],employees:state.employees.map(employee=>({employee_code:employee.employeeCode||'',name:employee.name||'',role:employee.role||'',department:employee.dept||'Operations',email:employee.email||'',phone:employee.phone||'',nic_passport:employee.nicPassport||'',start_date:employee.startDate||new Date().toISOString().slice(0,10),branch_index:Math.max(0,salonLocations.findIndex(branch=>branch.id===employee.location_id)),pay_type:String(employee.payType||'Monthly').toLowerCase(),base_salary:employee.salary||0,hourly_rate:employee.hourlyRate||0,standard_hours:employee.standardHours||0,allowances:employee.fixedAllowances||0,deductions:employee.fixedDeductions||0,payment_method:employee.paymentMethod||'bank',emergency_contact:employee.emergencyContact||'',emergency_phone:employee.emergencyPhone||'',address:employee.address||'',notes:employee.notes||''})),preferences:{...(orgSettings?.preferences||{})}};
 $('#appShell').classList.add('onboarding-active');renderOnboarding();
}

function renderOnboarding(){page.innerHTML=onboardingView();hydrateIcons(page);bindOnboarding()}
function bindOnboarding(){
 $$('[data-onboard-business]',page).forEach(button=>button.onclick=()=>{onboardingDraft.business_type=button.dataset.onboardBusiness;onboardingDraft.preferences={};renderOnboarding()});
 onboardingDraft.employees.forEach((employee,index)=>{const branch=$(`[data-onboard-employee="branch_index"][data-employee-index="${index}"]`,page);const payType=$(`[data-onboard-employee="pay_type"][data-employee-index="${index}"]`,page);const payment=$(`[data-onboard-employee="payment_method"][data-employee-index="${index}"]`,page);if(branch)branch.value=String(employee.branch_index??0);if(payType)payType.value=employee.pay_type||'monthly';if(payment)payment.value=employee.payment_method||'bank'});
 const branchCountField=$('[data-onboard-field="branch_count"]',page);if(branchCountField)branchCountField.onchange=()=>{collectOnboardingFields();onboardingDraft.branch_count=Math.max(1,Math.min(30,Number(onboardingDraft.branch_count)||1));renderOnboarding()};
 const back=$('[data-onboard-back]',page);if(back)back.onclick=()=>{collectOnboardingFields();onboardingStep-=1;renderOnboarding()};
 const next=$('[data-onboard-next]',page);if(next)next.onclick=async()=>{
  collectOnboardingFields();if(onboardingStep===1&&!onboardingDraft.business_type)return toast('Choose your business type');if(onboardingStep===2&&(!onboardingDraft.company_name||onboardingDraft.branch_count<1||onboardingDraft.employee_count<1))return toast('Complete the required company details');if(onboardingStep===2&&businessUsesLocations(onboardingDraft.business_type)&&onboardingDraft.locations.slice(0,onboardingDraft.branch_count).some(branch=>!branch.name))return toast('Add a name for every business location');if(onboardingStep===3&&onboardingDraft.employees.some(employee=>!employee.employee_code||!employee.name||!employee.role||Number(employee.base_salary)<0))return toast('Complete the employee ID, name, role, and valid salary for every employee');if(onboardingStep<4){onboardingStep+=1;renderOnboarding();return}
  next.disabled=true;next.textContent='Configuring workspace…';const {error}=await supabase.rpc('configure_business',{p_org_id:currentOrg.id,p_business_type:onboardingDraft.business_type,p_company_name:onboardingDraft.company_name,p_legal_name:onboardingDraft.legal_name||'',p_phone:onboardingDraft.phone||'',p_email:onboardingDraft.email||'',p_address:onboardingDraft.address||'',p_registration_number:onboardingDraft.registration_number||'',p_tax_number:onboardingDraft.tax_number||'',p_branch_count:onboardingDraft.branch_count,p_employee_count:onboardingDraft.employee_count,p_preferences:onboardingDraft.preferences});if(error){next.disabled=false;next.textContent='Activate workspace';return toast(error.message)}
 let configuredBranches=[];if(businessUsesLocations(onboardingDraft.business_type)){
   const existing=await supabase.from('salon_locations').select('*').eq('org_id',currentOrg.id).order('is_primary',{ascending:false}).order('created_at');if(existing.error){next.disabled=false;next.textContent='Activate workspace';return toast(existing.error.message)}
   const branches=[...(existing.data||[])];const requested=onboardingDraft.locations.slice(0,Number(onboardingDraft.branch_count));for(let index=0;index<requested.length;index++){const details=requested[index];if(branches[index]){const updated=await supabase.rpc('update_salon_location',{p_location_id:branches[index].id,p_name:details.name,p_code:branches[index].code||`BR${String(index+1).padStart(2,'0')}`,p_city:details.city||'',p_address:details.address||'',p_phone:details.phone||onboardingDraft.phone||'',p_active:true,p_is_primary:index===0});if(updated.error){next.disabled=false;next.textContent='Activate workspace';return toast(updated.error.message)}branches[index]=updated.data}else{const created=await supabase.rpc('create_salon_location',{p_org_id:currentOrg.id,p_name:details.name,p_code:`BR${String(index+1).padStart(2,'0')}`,p_city:details.city||'',p_address:details.address||'',p_phone:details.phone||onboardingDraft.phone||'',p_is_primary:index===0});if(created.error){next.disabled=false;next.textContent='Activate workspace';return toast(created.error.message)}branches.push(created.data)}}
   configuredBranches=branches;
  }
  const employeePayload=onboardingDraft.employees.map(employee=>({...employee,location_id:configuredBranches[Number(employee.branch_index)||0]?.id||null,bookable:onboardingDraft.business_type==='salon'}));const employeesSaved=await supabase.rpc('configure_onboarding_employees',{p_org_id:currentOrg.id,p_employees:employeePayload});if(employeesSaved.error){next.disabled=false;next.textContent='Activate workspace';return toast(employeesSaved.error.message)}
  await loadWorkspaceData();$('#appShell').classList.remove('onboarding-active');settingsSection=onboardingDraft.business_type==='salon'?'locations':'company';render(onboardingDraft.business_type==='salon'?'settings':'home');toast(`${activeBusinessProfile().label} workspace activated`)
 };
}

