function home(){
 const name=escapeHtml((userProfile?.full_name||'there').split(' ')[0]);
 const profile=activeBusinessProfile();
 const today=new Date();
 const lowStock=state.products.filter(p=>Number(p.stock)<=Number(p.reorder||15)).length;
 const openWork=profile.operation?liveIndustryOpenWork():profile===businessProfiles.pharmacy?prescriptions.filter(x=>!['dispensed','cancelled'].includes(x.status)).length:profile===businessProfiles.salon?salonAppointments.filter(x=>!['completed','cancelled','no_show'].includes(x.status)).length:profile===businessProfiles.automotive?workshopJobs.filter(x=>!['delivered','cancelled'].includes(x.status)).length:state.tasks.length;
 const workLabel=profile===businessProfiles.pharmacy?'Prescriptions waiting':profile===businessProfiles.salon?'Appointments today':profile===businessProfiles.automotive?'Open job cards':'Active work';
 const primaryRoute=profile.cards[0][0];
 return `<section class="focused-home"><div class="home-hero industry-${profile.color}"><div><span class="eyebrow">${escapeHtml(currentOrg?.name||'Your company')} · ${profile.label}</span><h1>Good ${today.getHours()<12?'morning':today.getHours()<18?'afternoon':'evening'}, ${name}</h1><p>${profile.tagline}</p><button class="home-primary-action" data-route-link="${primaryRoute}">${icon(profile.cards[0][3])} Open ${profile.cards[0][1]}</button></div><div class="home-date"><b>${today.toLocaleDateString('en-LK',{weekday:'long'})}</b><span>${today.toLocaleDateString('en-LK',{month:'long',day:'numeric',year:'numeric'})}</span><em>Workspace configured</em></div></div>
 <div class="home-kpis focused-kpis"><button data-route-link="${primaryRoute}"><span class="kpi-icon blue">${icon(profile.icon)}</span><span><small>${workLabel}</small><b>${openWork}</b></span><em>Open operations →</em></button><button data-route-link="inventory"><span class="kpi-icon orange">${icon('boxes')}</span><span><small>Low stock items</small><b>${lowStock}</b></span><em>Review stock →</em></button><button data-route-link="customers"><span class="kpi-icon purple">${icon('users')}</span><span><small>Customer profiles</small><b>${retailCustomers.length}</b></span><em>Customers & loyalty →</em></button><button data-route-link="finance"><span class="kpi-icon green">${icon('wallet')}</span><span><small>Open receivables</small><b>${lkr(state.invoices.filter(i=>i.status!=='Paid').reduce((sum,i)=>sum+i.amount,0))}</b></span><em>Finance →</em></button></div>
 <section class="home-workflow card"><div class="card-head"><div><span class="eyebrow">Your operating system</span><h2>${profile.label} workflow</h2><p>Only the tools your team needs, connected from first action to final accounts.</p></div><button class="btn small" data-route-link="settings">Configure</button></div><div class="focused-flow">${profile.flow.map((step,index)=>`<div><span>${String(index+1).padStart(2,'0')}</span><b>${step}</b>${index<profile.flow.length-1?'<i>→</i>':''}</div>`).join('')}</div></section>
 <section class="focused-modules"><div class="section-line"><div><h2>Your workspace</h2><p>Modules activated for ${profile.label}</p></div><span>${profile.modules.length} focused modules</span></div><div class="focused-module-grid">${profile.cards.map((card,index)=>`<button data-route-link="${card[0]}"><span class="launch-icon tone-${index}">${icon(card[3])}</span><span><b>${card[1]}</b><small>${card[2]}</small></span><em>Open →</em></button>`).join('')}</div></section>
 <div class="home-bottom"><article class="card"><div class="card-head"><div><h2>What needs attention</h2><p>Exceptions are shown before routine work</p></div><span class="status-pill ${lowStock?'orange':'green'}">${lowStock?'Action needed':'All clear'}</span></div><div class="activity-list"><div class="activity"><span class="activity-avatar">${lowStock?'!':'✓'}</span><p><b>${lowStock} products</b> are at or below their reorder level</p><small>Inventory</small></div><div class="activity"><span class="activity-avatar">${openWork}</span><p><b>${openWork} ${workLabel.toLowerCase()}</b> need operational attention</p><small>Today</small></div><div class="activity"><span class="activity-avatar">Rs</span><p><b>${state.invoices.filter(i=>i.status==='Overdue').length} overdue invoices</b> require follow-up</p><small>Finance</small></div></div></article><article class="card"><div class="card-head"><div><h2>Connected controls</h2><p>Built into every transaction</p></div><span class="status-pill green">Protected</span></div><div class="control-list"><span>${icon('check')} Inventory and cost posting</span><span>${icon('check')} Customer and loyalty history</span><span>${icon('check')} Role-based company access</span><span>${icon('check')} Double-entry financial audit</span></div></article></div></section>`;
}

function homeSupabaseLegacy(){
 const profile=activeBusinessProfile();const today=new Date();const firstName=escapeHtml((userProfile?.full_name||'there').split(' ')[0]);const primaryRoute=profile.cards[0][0];const lowStock=operationalProducts().filter(item=>Number(item.stock)<=Number(item.reorder||15)).length;const openWork=profile===businessProfiles.pharmacy?prescriptions.filter(item=>!['dispensed','cancelled'].includes(item.status)).length:profile===businessProfiles.salon?salonAppointments.filter(item=>!['completed','cancelled','no_show'].includes(item.status)&&new Date(item.starts_at).toDateString()===today.toDateString()).length:profile===businessProfiles.automotive?workshopJobs.filter(item=>!['delivered','cancelled'].includes(item.status)).length:state.tasks.filter(item=>item.status!=='Done').length;const outstanding=state.invoices.filter(item=>item.status!=='Paid').reduce((sum,item)=>sum+Number(item.amount||0),0);const attention=[{tone:lowStock?'warning':'success',icon:'boxes',title:lowStock?`${lowStock} items need reordering`:'Inventory is healthy',copy:lowStock?'Review purchasing before stock runs out.':'No items are below their reorder level.',route:'inventory'},{tone:openWork?'info':'success',icon:profile.icon,title:`${openWork} active operations`,copy:`Open the ${profile.cards[0][1].toLowerCase()} workspace to continue today’s work.`,route:primaryRoute},{tone:outstanding?'warning':'success',icon:'wallet',title:outstanding?`${lkr(outstanding)} outstanding`:'Accounts are clear',copy:outstanding?'Review unpaid and overdue customer balances.':'No receivables require attention.',route:'finance'}];
 return `<section class="home-supabase"><header class="sb-home-header"><div><span class="sb-breadcrumb">${escapeHtml(currentOrg?.name||'Workspace')} <i>/</i> ${escapeHtml(profile.short)}</span><h1>Good ${today.getHours()<12?'morning':today.getHours()<18?'afternoon':'evening'}, ${firstName}</h1><p>${escapeHtml(profile.tagline)}</p></div><div class="sb-home-actions"><span><i></i> All systems operational</span><button class="btn" data-route-link="settings">Settings</button><button class="btn sb-primary" data-route-link="${primaryRoute}">${icon('arrow')} Open workspace</button></div></header><div class="sb-project-strip"><div><span class="sb-project-icon">${icon(profile.icon)}</span><p><small>ACTIVE WORKSPACE</small><b>${escapeHtml(currentOrg?.name||'Your workspace')}</b><em>${escapeHtml(profile.label)} · ${salonLocations.length||Number(currentOrg?.branch_count||1)} ${salonLocations.length===1?'location':'locations'}</em></p></div><dl><div><dt>Environment</dt><dd><i></i> Production</dd></div><div><dt>Region</dt><dd>Asia / Colombo</dd></div><div><dt>Local time</dt><dd>${today.toLocaleTimeString('en-LK',{hour:'2-digit',minute:'2-digit'})}</dd></div></dl></div><div class="sb-metric-grid"><button data-route-link="${primaryRoute}"><span>${icon(profile.icon)}</span><small>Active operations</small><strong>${openWork}</strong><em>View live work →</em></button><button data-route-link="customers"><span>${icon('users')}</span><small>Customer profiles</small><strong>${retailCustomers.length}</strong><em>Shared across locations →</em></button><button data-route-link="inventory"><span>${icon('boxes')}</span><small>Low-stock items</small><strong>${lowStock}</strong><em>Review branch stock →</em></button><button data-route-link="finance"><span>${icon('wallet')}</span><small>Open receivables</small><strong>${lkr(outstanding)}</strong><em>Open finance →</em></button></div><div class="sb-home-grid"><article class="sb-panel sb-attention"><header><div><small>OPERATIONS</small><h2>Needs attention</h2></div><span>Live</span></header><div>${attention.map(item=>`<button data-route-link="${item.route}" class="${item.tone}"><i>${icon(item.icon)}</i><p><b>${escapeHtml(item.title)}</b><small>${escapeHtml(item.copy)}</small></p><span>→</span></button>`).join('')}</div></article><article class="sb-panel sb-quickstart"><header><div><small>QUICK START</small><h2>Workspace modules</h2></div><span>${profile.cards.length} enabled</span></header><div>${profile.cards.map(card=>`<button data-route-link="${card[0]}"><i>${icon(card[3])}</i><p><b>${escapeHtml(card[1])}</b><small>${escapeHtml(card[2])}</small></p><span>Open</span></button>`).join('')}</div></article></div><article class="sb-panel sb-workflow"><header><div><small>BUSINESS FLOW</small><h2>${escapeHtml(profile.label)} workflow</h2></div><button data-route-link="settings">Configure</button></header><div>${profile.flow.map((step,index)=>`<span><i>${String(index+1).padStart(2,'0')}</i><b>${escapeHtml(step)}</b>${index<profile.flow.length-1?'<em>→</em>':''}</span>`).join('')}</div></article></section>`;
}

function homeOperationalVisuals(profile,today){
 const dayKeys=[];const dayLabels=[];const dayTotals=[];
 for(let offset=6;offset>=0;offset--){const day=new Date(today);day.setHours(0,0,0,0);day.setDate(day.getDate()-offset);dayKeys.push(day.toDateString());dayLabels.push(day.toLocaleDateString('en-LK',{weekday:'short'}));dayTotals.push(0)}
 posRecentOrders.forEach(order=>{const stamp=new Date(order.created_at);const index=dayKeys.indexOf(stamp.toDateString());if(index>=0)dayTotals[index]+=Number(order.total||order.subtotal||0)});
 const max=Math.max(...dayTotals,1);const chartPoints=dayTotals.map((value,index)=>`${40+index*(520/6)},${164-(value/max)*124}`).join(' ');const weekTotal=dayTotals.reduce((sum,value)=>sum+value,0);const todayTotal=dayTotals.at(-1)||0;
 const openCount=profile.operation?liveIndustryOpenWork():profile===businessProfiles.salon?salonAppointments.filter(item=>!['completed','cancelled','no_show'].includes(item.status)).length:profile===businessProfiles.automotive?workshopJobs.filter(item=>!['delivered','cancelled'].includes(item.status)).length:state.tasks.filter(item=>item.status!=='Done').length;
 const lowCount=operationalProducts().filter(item=>Number(item.stock)<=Number(item.reorder||15)).length;const overdueCount=state.invoices.filter(item=>String(item.status).toLowerCase()==='overdue').length;const customerCount=retailCustomers.length;const signalTotal=Math.max(openCount+lowCount+overdueCount,1);const signalPercent=Math.round(Math.min(100,(openCount/signalTotal)*100));
 const activities=[
  ...posRecentOrders.slice(0,20).map(order=>({time:order.created_at,icon:'receipt',tone:'green',title:`Sale ${order.receipt_number||'completed'}`,copy:order.customer||'Walk-in customer',meta:lkr(order.total||order.subtotal||0),route:'sales_history'})),
  ...salonAppointments.slice(0,20).map(item=>({time:item.updated_at||item.created_at||item.starts_at,icon:'calendar',tone:'purple',title:`Booking - ${item.customer_name||'Customer'}`,copy:`${item.service_name||'Service'} - ${item.staff_name||item.responsible_name||'Unassigned'}`,meta:new Date(item.starts_at).toLocaleTimeString('en-LK',{hour:'numeric',minute:'2-digit'}),route:'salon'})),
  ...inventoryReceipts.slice(0,20).map(item=>({time:item.received_at||item.created_at,icon:'boxes',tone:'orange',title:item.reference_number||item.receipt_number||'Stock received',copy:item.supplier_name||'Inventory receipt',meta:lkr(item.total_cost||item.total||item.subtotal||0),route:'inventory'})),
  ...workshopJobs.slice(0,20).map(item=>({time:item.updated_at||item.created_at,icon:'settings',tone:'blue',title:`Job ${item.number||'card'}`,copy:item.vehicles?.registration_number||item.customer_name||item.complaint||'Workshop service',meta:String(item.status||'open').replaceAll('_',' '),route:'automotive'})),
  ...industryModuleRecords.slice(0,20).map(item=>({time:item.updated_at||item.created_at,icon:profile.icon,tone:'blue',title:item.title,copy:item.reference||profile.operation?.label||'Industry operation',meta:String(item.status||'open').replaceAll('_',' '),route:'industry_ops'}))
 ].filter(item=>item.time&&!Number.isNaN(new Date(item.time).getTime())).sort((a,b)=>new Date(b.time)-new Date(a.time)).slice(0,6);
 const branchCards=salonLocations.map((branch,index)=>{const branchOrders=posRecentOrders.filter(order=>order.location_id===branch.id);const branchProducts=operationalProducts().filter(item=>item.location_id===branch.id);const branchLow=branchProducts.filter(item=>Number(item.stock)<=Number(item.reorder||15)).length;const branchPeople=state.employees.filter(item=>item.location_id===branch.id).length;const branchBookings=salonAppointments.filter(item=>item.location_id===branch.id&&!['completed','cancelled','no_show'].includes(item.status)).length;const sales=branchOrders.reduce((sum,order)=>sum+Number(order.total||order.subtotal||0),0);const health=branchLow?Math.max(62,100-branchLow*6):100;return `<button data-route-link="settings" class="sb-branch-card"><header><span class="sb-branch-avatar tone-${index%4}">${escapeHtml((branch.code||branch.name||'BR').slice(0,2).toUpperCase())}</span><p><b>${escapeHtml(branch.name)}</b><small>${escapeHtml(branch.city||branch.address||'Location')} - ${branch.active===false?'Paused':'Online'}</small></p><em><i></i>${health}% health</em></header><div><span><small>Sales loaded</small><b>${lkr(sales)}</b></span><span><small>Team</small><b>${branchPeople}</b></span><span><small>Open work</small><b>${branchBookings}</b></span></div><footer><span>${branchProducts.length} stock items</span><span class="${branchLow?'warning':''}">${branchLow?`${branchLow} need reorder`:'Stock healthy'}</span></footer></button>`}).join('');
 return `<section class="sb-live-visuals"><article class="sb-panel sb-revenue-pulse"><header><div><small>REAL DATA / LAST 7 DAYS</small><h2>Revenue pulse</h2></div><span><i></i> Live from POS</span></header><div class="sb-chart-summary"><span><small>Today</small><b>${lkr(todayTotal)}</b></span><span><small>7-day total</small><b>${lkr(weekTotal)}</b></span><span><small>Daily average</small><b>${lkr(weekTotal/7)}</b></span></div><div class="sb-live-chart"><svg viewBox="0 0 600 180" preserveAspectRatio="none" role="img" aria-label="Seven day revenue chart"><defs><linearGradient id="sbRevenueArea" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3ecf8e" stop-opacity=".28"/><stop offset="1" stop-color="#3ecf8e" stop-opacity="0"/></linearGradient></defs><g class="revenue-grid">${[40,81,123,164].map(y=>`<line x1="12" x2="588" y1="${y}" y2="${y}"/>`).join('')}</g>${dayTotals.map((value,index)=>`<rect class="revenue-bar" x="${24+index*(520/6)}" y="${164-(value/max)*124}" width="32" height="${value/max*124}" rx="4"><title>${dayLabels[index]}: ${lkr(value)}</title></rect>`).join('')}<polyline class="line" points="${chartPoints}"/>${dayTotals.map((value,index)=>`<circle cx="${40+index*(520/6)}" cy="${164-(value/max)*124}" r="4"><title>${dayLabels[index]}: ${lkr(value)}</title></circle>`).join('')}</svg><footer>${dayLabels.map((label,index)=>`<span><b>${label}</b><small>${dayTotals[index]?lkr(dayTotals[index]):'No sales'}</small></span>`).join('')}</footer></div></article><article class="sb-panel sb-operational-signal"><header><div><small>WORKSPACE SIGNAL</small><h2>What is moving now</h2></div><span>Live</span></header><div class="sb-signal-visual"><div class="sb-signal-ring" style="--signal:${signalPercent*3.6}deg"><span><b>${openCount+lowCount+overdueCount}</b><small>signals</small></span></div><div><span><i class="green"></i><p><b>${openCount}</b><small>Open operations</small></p></span><span><i class="orange"></i><p><b>${lowCount}</b><small>Low-stock items</small></p></span><span><i class="purple"></i><p><b>${overdueCount}</b><small>Overdue invoices</small></p></span><span><i class="blue"></i><p><b>${customerCount}</b><small>Customer profiles</small></p></span></div></div><footer><button data-route-link="${profile.cards[0][0]}">Open operations</button><button data-route-link="inventory">Review inventory</button></footer></article></section><section class="sb-real-data-row"><article class="sb-panel sb-activity-feed"><header><div><small>CONNECTED ACTIVITY</small><h2>Latest across your business</h2></div><span>${activities.length} recent</span></header><div>${activities.length?activities.map(item=>`<button data-route-link="${item.route}"><i class="${item.tone}">${icon(item.icon)}</i><p><b>${escapeHtml(item.title)}</b><small>${escapeHtml(item.copy)}</small></p><time>${escapeHtml(item.meta)}<small>${new Date(item.time).toLocaleString('en-LK',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</small></time></button>`).join(''):`<div class="sb-live-empty">${icon('trend')}<b>Your live activity will appear here</b><small>Complete a sale, booking, receipt, or job card to start the feed.</small></div>`}</div></article><article class="sb-panel sb-branch-health"><header><div><small>BRANCH NETWORK</small><h2>Location health</h2></div><button data-route-link="settings">Manage</button></header><div>${branchCards||`<div class="sb-live-empty">${icon('store')}<b>No locations configured yet</b><small>Add branches to compare staff, stock, sales, and live work here.</small><button data-route-link="settings">Configure locations</button></div>`}</div></article></section>`;
}

function homeSupabase(){
 const profile=activeBusinessProfile();const today=new Date();const firstName=escapeHtml((userProfile?.full_name||'there').split(' ')[0]);const primaryRoute=profile.cards[0][0];const lowStock=operationalProducts().filter(item=>Number(item.stock)<=Number(item.reorder||15)).length;const openWork=profile.operation?liveIndustryOpenWork():profile===businessProfiles.pharmacy?prescriptions.filter(item=>!['dispensed','cancelled'].includes(item.status)).length:profile===businessProfiles.salon?salonAppointments.filter(item=>!['completed','cancelled','no_show'].includes(item.status)&&new Date(item.starts_at).toDateString()===today.toDateString()).length:profile===businessProfiles.automotive?workshopJobs.filter(item=>!['delivered','cancelled'].includes(item.status)).length:state.tasks.filter(item=>item.status!=='Done').length;const outstanding=state.invoices.filter(item=>item.status!=='Paid').reduce((sum,item)=>sum+Number(item.amount||0),0);const attention=[{tone:lowStock?'warning':'success',icon:'boxes',title:lowStock?`${lowStock} items need reordering`:'Inventory is healthy',copy:lowStock?'Review purchasing before stock runs out.':'No items are below their reorder level.',route:'inventory'},{tone:openWork?'info':'success',icon:profile.icon,title:`${openWork} active operations`,copy:`Open the ${profile.cards[0][1].toLowerCase()} workspace to continue today's work.`,route:primaryRoute},{tone:outstanding?'warning':'success',icon:'wallet',title:outstanding?`${lkr(outstanding)} outstanding`:'Accounts are clear',copy:outstanding?'Review unpaid and overdue customer balances.':'No receivables require attention.',route:'finance'}];
 return `<section class="home-supabase"><header class="sb-home-header"><div><span class="sb-breadcrumb">${escapeHtml(currentOrg?.name||'Workspace')} <i>/</i> ${escapeHtml(profile.short)}</span><h1>Good ${today.getHours()<12?'morning':today.getHours()<18?'afternoon':'evening'}, ${firstName}</h1><p>${escapeHtml(profile.tagline)}</p></div><div class="sb-home-actions"><span><i></i> All systems operational</span><button class="btn" data-route-link="settings">Settings</button><button class="btn sb-primary" data-route-link="${primaryRoute}">${icon('arrow')} Open workspace</button></div></header><div class="sb-project-strip"><div><span class="sb-project-icon">${icon(profile.icon)}</span><p><small>ACTIVE WORKSPACE</small><b>${escapeHtml(currentOrg?.name||'Your workspace')}</b><em>${escapeHtml(profile.label)} - ${salonLocations.length||Number(currentOrg?.branch_count||1)} ${salonLocations.length===1?'location':'locations'}</em></p></div><dl><div><dt>Environment</dt><dd><i></i> Production</dd></div><div><dt>Region</dt><dd>Asia / Colombo</dd></div><div><dt>Local time</dt><dd data-live-clock>${today.toLocaleTimeString('en-LK',{hour:'2-digit',minute:'2-digit'})}</dd></div></dl></div><div class="sb-metric-grid"><button data-route-link="${primaryRoute}"><span>${icon(profile.icon)}</span><small>Active operations</small><strong>${openWork}</strong><em>View live work &rarr;</em></button><button data-route-link="customers"><span>${icon('users')}</span><small>Customer profiles</small><strong>${retailCustomers.length}</strong><em>Shared across locations &rarr;</em></button><button data-route-link="inventory"><span>${icon('boxes')}</span><small>Low-stock items</small><strong>${lowStock}</strong><em>Review branch stock &rarr;</em></button><button data-route-link="finance"><span>${icon('wallet')}</span><small>Open receivables</small><strong>${lkr(outstanding)}</strong><em>Open finance &rarr;</em></button></div>${homeOperationalVisuals(profile,today)}<div class="sb-home-grid"><article class="sb-panel sb-attention"><header><div><small>OPERATIONS</small><h2>Needs attention</h2></div><span>Live</span></header><div>${attention.map(item=>`<button data-route-link="${item.route}" class="${item.tone}"><i>${icon(item.icon)}</i><p><b>${escapeHtml(item.title)}</b><small>${escapeHtml(item.copy)}</small></p><span>&rarr;</span></button>`).join('')}</div></article><article class="sb-panel sb-quickstart"><header><div><small>QUICK START</small><h2>Workspace modules</h2></div><span>${profile.cards.length} enabled</span></header><div>${profile.cards.map(card=>`<button data-route-link="${card[0]}"><i>${icon(card[3])}</i><p><b>${escapeHtml(card[1])}</b><small>${escapeHtml(card[2])}</small></p><span>Open</span></button>`).join('')}</div></article></div><article class="sb-panel sb-workflow"><header><div><small>BUSINESS FLOW</small><h2>${escapeHtml(profile.label)} workflow</h2></div><button data-route-link="settings">Configure</button></header><div>${profile.flow.map((step,index)=>`<span><i>${String(index+1).padStart(2,'0')}</i><b>${escapeHtml(step)}</b>${index<profile.flow.length-1?'<em>&rarr;</em>':''}</span>`).join('')}</div></article></section>`;
}

