  Sales:['Capture demand','Qualify and price','Confirm order','Deliver service','Invoice and renew'],
  Finance:['Collect documents','Validate entries','Post transactions','Reconcile accounts','Close and report'],
  Operations:['Plan demand','Source materials','Execute operations','Control quality','Deliver and analyze'],
  People:['Attract people','Onboard team','Manage work','Develop performance','Reward and retain'],
  Marketing:['Define audience','Create content','Launch journey','Engage contacts','Attribute results'],
  Services:['Scope work','Plan resources','Deliver tasks','Track time and SLA','Invoice profitability'],
  Website:['Create experience','Publish content','Acquire visitors','Convert customers','Retain community'],
  Productivity:['Capture knowledge','Collaborate','Request approval','Automate action','Audit outcome'],
