const moduleKey=(app)=>app?.[0]?.toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'module';
async function openApplication(app){
 if(!app)return;
 activeApplication=app;
 if(app[0]==='Point of Sale'){render('pos');return}
 if(app[0]==='Payroll'||app[0]==='Employees'){render('people');return}
 if(app[0]==='Inventory'){render('inventory');return}
 let query;
 if(app[0]==='Sales')query=supabase.from('sales_orders').select('*').eq('org_id',currentOrg.id).order('created_at',{ascending:false});
 else if(app[0]==='Accounting')query=supabase.from('journal_entries').select('*').eq('org_id',currentOrg.id).order('created_at',{ascending:false});
 else query=supabase.from('module_records').select('*').eq('org_id',currentOrg.id).eq('module_key',moduleKey(app)).order('created_at',{ascending:false});
 const {data,error}=await query;
 if(error){toast(error.message);return}
 moduleRecords=app[0]==='Sales'?(data||[]).map(r=>({...r,title:r.customer,reference:r.number,amount:r.total_amount,due_date:r.valid_until})):app[0]==='Accounting'?(data||[]).map(r=>({...r,title:r.description||r.reference,amount:null,due_date:r.entry_date})):data||[];render('module');
}

function moduleWorkspace(){
 const a=activeApplication||launcherApps[0];const workflows=categoryWorkflows[a[1]]||categoryWorkflows.Industries;
 const rows=moduleRecords.map(r=>`<tr data-search="${r.title} ${r.reference||''} ${r.status}"><td><div class="record-main"><span class="record-icon">${a[0].slice(0,2).toUpperCase()}</span><span><strong>${r.title}</strong><small>${r.reference||'No reference'}</small></span></div></td><td><span class="status-pill ${statusClass(r.status)}">${r.status}</span></td><td>${r.amount==null?'—':money(Number(r.amount))}</td><td>${r.due_date||'—'}</td><td>${a[0]==='Sales'&&['draft','sent'].includes(r.status)?`<button class="btn small primary" data-confirm-order="${r.id}">Confirm & invoice</button>`:a[0]==='Accounting'?`<button class="btn small">View entry</button>`:`<button class="btn small" data-record-status="${r.id}">Advance</button>`}</td></tr>`).join('');
 return `${header(a[0],a[4],a[0]==='Sales'?'New quotation':`New ${a[0]} record`,'Export data')}<div class="module-breadcrumb"><button data-launch-home>${icon('grid')} All apps</button><span>›</span><b>${a[1]}</b><span>›</span><strong>${a[0]}</strong></div><nav class="module-tabs"><button class="active">Overview</button><button>Operations</button><button>Reporting</button><button>Configuration</button></nav><div class="stat-grid"><div class="stat-panel"><span>Total records</span><strong>${moduleRecords.length}</strong><small>In this workspace only</small></div><div class="stat-panel"><span>Active</span><strong>${moduleRecords.filter(r=>!['done','closed','cancelled','posted'].includes(r.status)).length}</strong><small>Current workload</small></div><div class="stat-panel"><span>Completed</span><strong>${moduleRecords.filter(r=>['done','closed','completed','confirmed','posted'].includes(r.status)).length}</strong><small>All-time output</small></div><div class="stat-panel"><span>Automation</span><strong>Ready</strong><small>Rules and activities enabled</small></div></div><div class="split-grid"><article class="card"><div class="card-head"><div><h2>${a[0]} workflow</h2><p>A connected end-to-end operating flow</p></div><span class="status-pill green">Configured</span></div><div class="workflow-strip">${workflows.map((w,i)=>`<div><span>${i+1}</span><b>${w}</b>${i<workflows.length-1?'<i>→</i>':''}</div>`).join('')}</div><div class="card-head records-head"><div><h2>Records</h2><p>${a[0]==='Sales'?'Confirmation checks stock, creates delivery movements, invoices, and balanced journal entries.':'Search, filter, group, import, export, and schedule activities'}</p></div>${a[0]==='Accounting'?'':`<button class="btn small" data-create>${icon('plus')} New</button>`}</div>${toolbar(`Search ${a[0].toLowerCase()} records...`)}<div class="table-wrap module-table"><table class="data-table"><thead><tr><th>Record</th><th>Status</th><th>Amount</th><th>Due</th><th>Action</th></tr></thead><tbody>${rows||`<tr><td colspan="5"><div class="empty-state"><b>No records yet</b><p>Create the first ${a[0]} record for ${currentOrg?.name||'your workspace'}.</p>${a[0]==='Accounting'?'':`<button class="btn primary" data-create>${icon('plus')} Create record</button>`}</div></td></tr>`}</tbody></table></div></article><div class="stack"><article class="card"><div class="card-head"><div><h2>Application capabilities</h2><p>Included in this system</p></div></div><div class="capability-list"><div>${icon('list')}<span><b>Flexible records</b><small>List, kanban, calendar, activity, and reporting views</small></span></div><div>${icon('message')}<span><b>Connected collaboration</b><small>Followers, notes, messages, and scheduled activities</small></span></div><div>${icon('settings')}<span><b>Workflow automation</b><small>Rules, approval gates, reminders, and webhooks</small></span></div><div>${icon('chart')}<span><b>Live reporting</b><small>KPIs, pivots, charts, exports, and spreadsheet analysis</small></span></div><div>${icon('users')}<span><b>Role-based access</b><small>Owner, admin, manager, member, and viewer permissions</small></span></div></div></article><article class="card"><div class="card-head"><div><h2>Related apps</h2><p>Shared data, no duplicate entry</p></div></div><div class="related-apps">${launcherApps.filter(x=>x[1]===a[1]&&x[0]!==a[0]).slice(0,4).map(x=>`<button data-open-app="${x[0]}"><span>${x[0][0]}</span>${x[0]}</button>`).join('')}</div></article></div></div>`;
}

function industryOperations(){
 if(currentOrg?.business_type==='hotel')return hotelOperations();
 if(currentOrg?.business_type==='healthcare_clinic')return medicalOperations();
 const profile=activeBusinessProfile();const operation=profile.operation;
 if(!operation)return erpOverview();
 const finalStatus=operation.statuses.at(-1);const active=industryModuleRecords.filter(record=>record.status!==finalStatus);const overdue=active.filter(record=>record.due_date&&new Date(`${record.due_date}T23:59:59`)<new Date());const value=industryModuleRecords.reduce((sum,record)=>sum+Number(record.amount||0),0);
 const columns=operation.statuses.map((status,index)=>{const records=industryModuleRecords.filter(record=>record.status===status);return `<section class="industry-stage"><header><span>${String(index+1).padStart(2,'0')}</span><b>${escapeHtml(status.replaceAll('_',' '))}</b><em>${records.length}</em></header><div>${records.map(record=>{const details=Object.entries(record.data||{}).filter(([,item])=>item!==''&&item!=null).slice(0,3).map(([key,item])=>`<small><b>${escapeHtml(key.replaceAll('_',' '))}</b>${escapeHtml(item)}</small>`).join('');return `<article data-search="${escapeHtml(`${record.title} ${record.reference||''} ${status}`)}"><span>${escapeHtml(record.reference||operation.recordType.replaceAll('_',' '))}</span><h3>${escapeHtml(record.title)}</h3>${details?`<div>${details}</div>`:''}<footer><p>${record.due_date?`Due ${new Date(`${record.due_date}T00:00:00`).toLocaleDateString('en-LK',{month:'short',day:'numeric'})}`:'No due date'}${record.amount!=null?`<b>${lkr(record.amount)}</b>`:''}</p>${status!==finalStatus?`<button data-industry-advance="${record.id}">Advance &rarr;</button>`:'<em>Complete</em>'}</footer></article>`}).join('')||'<div class="industry-stage-empty">No records</div>'}</div></section>`}).join('');
 return `${header(operation.label,operation.description,`New ${operation.singular}`,'Export workflow')}${toolbar(`Search ${operation.label.toLowerCase()}...`)}<div class="stat-grid industry-kpis"><div class="stat-panel"><span>Active ${escapeHtml(operation.singular)}s</span><strong>${active.length}</strong><small>Across this workspace only</small></div><div class="stat-panel"><span>Completed</span><strong>${industryModuleRecords.filter(industryRecordIsComplete).length}</strong><small>Finished workflow records</small></div><div class="stat-panel"><span>Due attention</span><strong>${overdue.length}</strong><small>Open records past due</small></div><div class="stat-panel"><span>Tracked value</span><strong>${lkr(value)}</strong><small>Operational value in this module</small></div></div><article class="card industry-workflow-card"><div class="card-head"><div><span class="eyebrow">${escapeHtml(profile.label)}</span><h2>${escapeHtml(operation.label)} workflow</h2><p>Records are isolated under <code>${escapeHtml(operation.key)}</code> and cannot be opened by another industry profile.</p></div><button class="btn small primary" data-create>${icon('plus')} New ${escapeHtml(operation.singular)}</button></div><div class="industry-stage-board">${columns}</div></article>`;
}

async function loadIndustryModuleRecords(){
 const operation=industryOperation();if(!operation){industryModuleRecords=[];return true}
 const result=await supabase.from('module_records').select('*').eq('org_id',currentOrg.id).eq('module_key',operation.key).order('created_at',{ascending:false});
 if(result.error){toast(result.error.message);return false}industryModuleRecords=result.data||[];return true;
}

function openIndustryRecordModal(){
 const operation=industryOperation();if(!operation)return;
 const fields=[['Title','title','text',true],['Reference','reference','text',false],['Value (LKR)','amount','number',false],['Due date','due_date','date',false],...operation.fields.map(([label,name,type='text'])=>[label,name,type,false])];
 const layer=$('#modalLayer');layer.innerHTML=`<div class="modal-backdrop" data-close-modal></div><section class="modal industry-record-modal"><header><div><span class="eyebrow">${escapeHtml(activeBusinessProfile().label)}</span><h2>New ${escapeHtml(operation.singular)}</h2><p>${escapeHtml(operation.description)}</p></div><button class="icon-button" data-close-modal>${icon('x')}</button></header><div class="modal-body"><form id="industryRecordForm"><div class="field-grid">${fields.map(([label,name,type,required])=>`<div class="field ${type==='textarea'?'full':''}"><label>${escapeHtml(label)}</label>${type==='textarea'?`<textarea name="${name}" rows="4" ${required?'required':''}></textarea>`:`<input name="${name}" type="${type}" ${required?'required':''}>`}</div>`).join('')}</div><div class="modal-actions"><button type="button" class="btn" data-close-modal>Cancel</button><button type="submit" class="btn primary">Create ${escapeHtml(operation.singular)}</button></div></form></div></section>`;layer.classList.add('open');layer.setAttribute('aria-hidden','false');hydrateIcons(layer);$$('[data-close-modal]',layer).forEach(button=>button.onclick=closeModal);const form=$('#industryRecordForm',layer);form.onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form));const submit=$('[type="submit"]',form);submit.disabled=true;submit.textContent='Creating...';const data=Object.fromEntries(operation.fields.map(([,name])=>[name,values[name]||'']));const result=await supabase.from('module_records').insert({org_id:currentOrg.id,module_key:operation.key,record_type:operation.recordType,title:values.title.trim(),reference:values.reference?.trim()||null,amount:values.amount?Number(values.amount):null,due_date:values.due_date||null,status:operation.statuses[0],data,created_by:session.user.id}).select().single();if(result.error){submit.disabled=false;submit.textContent=`Create ${operation.singular}`;return toast(result.error.message)}closeModal();await loadIndustryModuleRecords();render('industry_ops');toast(`${operation.singular} created`)};setTimeout(()=>form.elements.title.focus(),40);
}

const dateInputValue=date=>{const value=new Date(date);return new Date(value.getTime()-value.getTimezoneOffset()*60000).toISOString().slice(0,10)};
const slugValue=value=>String(value||'').toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,52);
const activeBranchId=()=>activeSalonLocationId==='all'?(salonLocations.find(branch=>branch.is_primary)?.id||salonLocations[0]?.id):activeSalonLocationId;
const activeHotelProperty=()=>hotelProperties.find(item=>item.location_id===activeBranchId())||hotelProperties[0]||null;
const activeMedicalCenter=()=>medicalCenters.find(item=>item.location_id===activeBranchId())||medicalCenters[0]||null;
const publicUrl=(kind,slug)=>`${window.location.origin}/${kind}/${slug}`;

function hotelOperations(){
 const property=activeHotelProperty();
 if(!property)return `${operationalLocationSwitcher('Hotel')}<section class="module-empty-setup"><span>${icon('home')}</span><small>HOTEL OPERATING SYSTEM</small><h1>Set up this hotel branch</h1><p>Add the property profile first, then room types, nightly rates, photos, booking inventory, and channel connections.</p><button class="btn primary" data-hotel-property>${icon('plus')} Add hotel details</button></section>`;
 const rooms=hotelRoomTypes.filter(room=>room.property_id===property.id&&room.active!==false);
 const bookings=hotelBookings.filter(booking=>booking.property_id===property.id);
 const activeBookings=bookings.filter(booking=>!['cancelled','no_show'].includes(booking.status));
 const dates=Array.from({length:14},(_,index)=>{const date=new Date(hotelCalendarStart);date.setDate(date.getDate()+index);return date});
 const roomNights=dates.reduce((total,date)=>total+activeBookings.filter(booking=>dateInputValue(date)>=booking.arrival_date&&dateInputValue(date)<booking.departure_date).reduce((sum,item)=>sum+Number(item.rooms_requested||1),0),0);
 const capacityNights=rooms.reduce((sum,room)=>sum+Number(room.room_count||0),0)*dates.length;
 const occupancy=capacityNights?Math.round(roomNights/capacityNights*100):0;
 const revenue=bookings.filter(item=>!['cancelled','no_show'].includes(item.status)).reduce((sum,item)=>sum+Number(item.total_amount||0),0);
 const arriving=bookings.filter(item=>item.arrival_date===dateInputValue(new Date())&&!['cancelled','no_show'].includes(item.status)).length;
 const matrix=rooms.map(room=>`<div class="hotel-matrix-row"><div class="hotel-room-axis"><b>${escapeHtml(room.name)}</b><small>${room.room_count} rooms</small></div>${dates.map(date=>{const day=dateInputValue(date);const dayBookings=activeBookings.filter(item=>item.room_type_id===room.id&&day>=item.arrival_date&&day<item.departure_date);const used=dayBookings.reduce((sum,item)=>sum+Number(item.rooms_requested||1),0);const remaining=Math.max(Number(room.room_count)-used,0);return `<button class="hotel-inventory-cell ${remaining===0?'full':remaining<=1?'limited':''}" title="${escapeHtml(`${room.name}: ${used} booked, ${remaining} available`)}"><b>${used||'–'}</b><small>${remaining} left</small></button>`}).join('')}</div>`).join('');
 const roomCards=rooms.map(room=>`<article class="hotel-room-card">${room.images?.[0]?`<img src="${escapeHtml(room.images[0])}" alt="${escapeHtml(room.name)}">`:`<div class="hotel-room-placeholder">${icon('home')}</div>`}<div><span>${escapeHtml(room.code)} · ${room.room_count} rooms</span><h3>${escapeHtml(room.name)}</h3><p>${escapeHtml(room.description||'No room description yet.')}</p><div class="room-includes">${(room.includes||[]).slice(0,4).map(item=>`<em>${escapeHtml(item)}</em>`).join('')}</div><footer><b>${lkr(room.nightly_rate)} <small>/ night</small></b><span>${room.max_adults} adults · ${room.max_children} children</span></footer></div></article>`).join('');
 const bookingRows=bookings.slice(0,100).map(booking=>{const room=rooms.find(item=>item.id===booking.room_type_id);const next={pending:'confirmed',confirmed:'checked_in',checked_in:'checked_out'}[booking.status];return `<tr data-search="${escapeHtml(`${booking.booking_number} ${booking.guest_name} ${booking.whatsapp}`)}"><td><b>${escapeHtml(booking.booking_number)}</b><small class="table-sub">${escapeHtml(booking.source)}</small></td><td><b>${escapeHtml(booking.guest_name)}</b><small class="table-sub">${escapeHtml(booking.whatsapp)}</small></td><td>${escapeHtml(room?.name||'Room')}<small class="table-sub">${booking.rooms_requested} room(s)</small></td><td>${new Date(`${booking.arrival_date}T00:00:00`).toLocaleDateString('en-LK',{month:'short',day:'numeric'})} → ${new Date(`${booking.departure_date}T00:00:00`).toLocaleDateString('en-LK',{month:'short',day:'numeric'})}</td><td><b>${lkr(booking.total_amount)}</b><small class="table-sub">Paid ${lkr(booking.paid_amount)}</small></td><td><span class="status-pill ${statusClass(booking.status)}">${escapeHtml(booking.status.replaceAll('_',' '))}</span></td><td><div class="row-actions">${next?`<button class="btn small primary" data-hotel-status="${booking.id}" data-next-status="${next}">${next.replaceAll('_',' ')}</button>`:''}<button class="btn small" data-hotel-invoice="${booking.id}">Invoice</button></div></td></tr>`}).join('');
 const channels=hotelChannels.filter(item=>item.property_id===property.id);const providers=['Agoda','Booking.com','Tripadvisor','Expedia','Custom API'];
 return `${operationalLocationSwitcher('Hotel')}<div class="hotel-command-head"><div><span class="eyebrow">${escapeHtml(property.name)} · HOTEL CONTROL</span><h1>Rooms, bookings, and availability</h1><p>One inventory ledger for direct and external reservations. Capacity is locked in the database before every booking.</p></div><div class="head-actions"><button class="btn" data-copy-value="${escapeHtml(publicUrl('hotel',property.public_slug))}">${icon('link')} Copy guest link</button><button class="btn" data-hotel-room>${icon('plus')} Room type</button><button class="btn primary" data-hotel-booking>${icon('calendar')} New booking</button></div></div>
 <div class="hotel-kpis"><article><span>Occupancy · 14 days</span><b>${occupancy}%</b><div><i style="width:${occupancy}%"></i></div><small>${roomNights} of ${capacityNights} room nights</small></article><article><span>Booking value</span><b>${lkr(revenue)}</b><small>${activeBookings.length} active reservations</small></article><article><span>Arrivals today</span><b>${arriving}</b><small>Prepare front desk and rooms</small></article><article><span>Public booking</span><b class="live-word">LIVE</b><small>/${escapeHtml(property.public_slug)}</small></article></div>
 <section class="card hotel-calendar-card"><div class="card-head"><div><h2>Availability control</h2><p>Room types on the Y-axis and stay dates on the X-axis. Each cell shows booked and remaining physical rooms.</p></div><div class="calendar-nav"><button class="btn small" data-hotel-calendar="prev">← 14 days</button><button class="btn small" data-hotel-calendar="today">Today</button><button class="btn small" data-hotel-calendar="next">14 days →</button></div></div><div class="hotel-matrix-scroll"><div class="hotel-matrix" style="--hotel-days:${dates.length}"><div class="hotel-matrix-head"><div class="hotel-room-axis"><b>Room / date</b></div>${dates.map(date=>`<div class="hotel-date-axis ${dateInputValue(date)===dateInputValue(new Date())?'today':''}"><small>${date.toLocaleDateString('en-LK',{weekday:'short'})}</small><b>${date.getDate()}</b><span>${date.toLocaleDateString('en-LK',{month:'short'})}</span></div>`).join('')}</div>${matrix||'<div class="empty-state"><b>No room types</b><p>Add a room type to start inventory planning.</p></div>'}</div></div></section>
 <div class="hotel-content-grid"><section class="card"><div class="card-head"><div><h2>Room types</h2><p>Capacity, price, inclusions, and up to five guest-facing photos.</p></div><button class="btn small primary" data-hotel-room>${icon('plus')} Add room type</button></div><div class="hotel-room-grid">${roomCards||'<div class="empty-state"><b>No rooms configured</b><p>Add the first room type and its physical room count.</p></div>'}</div></section><aside class="card hotel-link-card"><span>${icon('link')}</span><small>SHAREABLE BOOKING LINK</small><h3>${escapeHtml(property.name)}</h3><p>Guests can check live capacity and book without signing in.</p><input readonly value="${escapeHtml(publicUrl('hotel',property.public_slug))}"><button class="btn primary" data-copy-value="${escapeHtml(publicUrl('hotel',property.public_slug))}">Copy link</button></aside></div>
 <section class="card hotel-bookings-card"><div class="card-head"><div><h2>All bookings</h2><p>Direct and channel reservations use the same protected capacity.</p></div>${toolbar('Search guest, booking, or phone…')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Booking</th><th>Guest</th><th>Room</th><th>Stay</th><th>Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>${bookingRows||'<tr><td colspan="7"><div class="empty-state"><b>No bookings yet</b><p>Share the guest link or create a front-desk booking.</p></div></td></tr>'}</tbody></table></div></section>
 <section class="card hotel-channels"><div class="card-head"><div><h2>Booking channel connections</h2><p>Add provider identifiers and API endpoints here. Imported reservations must enter this same inventory ledger to prevent overbooking.</p></div><button class="btn small" data-hotel-channel>${icon('plus')} Add connection</button></div><div class="channel-grid">${providers.map(provider=>{const item=channels.find(channel=>channel.provider===provider);return `<article><span>${provider.slice(0,2).toUpperCase()}</span><div><b>${provider}</b><small>${item?`${item.status}${item.last_sync_at?` · synced ${new Date(item.last_sync_at).toLocaleString('en-LK')}`:''}`:'Not configured'}</small></div><button class="btn small" data-hotel-channel="${escapeHtml(provider)}">${item?'Edit':'Connect'}</button></article>`}).join('')}</div></section>`;
}

