function openMedicalPaymentModal(ticket){
 const balance=Math.max(Number(ticket.consultation_fee||0)-Number(ticket.paid_amount||0),0);if(balance<=0)return toast('This medical invoice is already paid');openFormModal('Record medical payment',ticket.invoice_number||ticket.display_number,[{label:'Patient',name:'patient',value:ticket.patient_name,full:true,required:false},{label:'Amount (LKR)',name:'amount',type:'number',min:0.01,step:'0.01',value:balance},{label:'Payment method',name:'method',type:'select',options:['cash','card','bank_transfer','mobile_payment']}],async values=>{const result=await supabase.rpc('record_medical_queue_payment',{p_ticket_id:ticket.id,p_amount:Number(values.amount),p_method:values.method});if(result.error){toast(result.error.message);return false}await loadWorkspaceData();render('industry_ops');toast(`Payment recorded for ${ticket.invoice_number}`);setTimeout(()=>printMedicalInvoice(result.data),80);return true},'Record & print invoice');
}

