 const center=activeMedicalCenter();if(!center)return;const url=`${publicUrl('medical',center.public_slug)}?source=qr`;const qr=await QRCode.toDataURL(url,{width:420,margin:2,color:{dark:'#172033',light:'#ffffff'}});const layer=$('#modalLayer');layer.innerHTML=`<div class="modal-backdrop" data-close-modal></div><section class="modal medical-qr-modal"><header><div><span class="eyebrow">PATIENT SELF-SERVICE</span><h2>Scan for a queue number</h2></div><button class="icon-button" data-close-modal>${icon('x')}</button></header><div class="modal-body"><div class="qr-sheet" id="medicalQrSheet"><img src="${qr}" alt="QR code for ${escapeHtml(center.name)}"><h2>${escapeHtml(center.name)}</h2><p>Scan to choose a doctor or join the first available queue.</p><strong>${escapeHtml(url)}</strong></div><div class="modal-actions"><button class="btn" data-copy-value="${escapeHtml(url)}">Copy link</button><button class="btn primary" data-print-medical-qr>Print QR</button></div></div></section>`;layer.classList.add('open');layer.setAttribute('aria-hidden','false');hydrateIcons(layer);$$('[data-close-modal]',layer).forEach(button=>button.onclick=closeModal);$('[data-copy-value]',layer).onclick=()=>navigator.clipboard.writeText(url).then(()=>toast('Queue link copied'));$('[data-print-medical-qr]',layer).onclick=()=>openPrintableDocument(`${center.name} queue QR`,`<div style="text-align:center;padding:28px"><img src="${qr}" style="width:320px"><h1>${escapeHtml(center.name)}</h1><p>Scan to get your patient number</p><small>${escapeHtml(url)}</small></div>`);
