function openPaysheetModal(employeeId=''){
 if(!state.employees.length)return toast('Add an employee before creating a paysheet');const layer=$('#modalLayer');const employeeOptions=state.employees.filter(employee=>employee.employmentStatus==='active').map(employee=>`<option value="${employee.id}" ${employee.id===employeeId?'selected':''}>${escapeHtml(employee.employeeCode||'No ID')} · ${escapeHtml(employee.name)}</option>`).join('');
 const adjustmentRows=(kind,labels)=>labels.map((label,index)=>`<div class="paysheet-adjustment"><input name="${kind}_label_${index}" value="${label}" aria-label="${kind} label"><input name="${kind}_amount_${index}" type="number" min="0" step="0.01" value="0" aria-label="${kind} amount"></div>`).join('');
 layer.innerHTML=`<div class="modal-backdrop" data-close-modal></div><section class="modal paysheet-modal"><div class="modal-head"><div><span class="eyebrow">Payroll · manual paysheet</span><h2>Create employee paysheet</h2><p>Select one employee and enter this month's additions and reductions.</p></div><button class="modal-close" data-close-modal>×</button></div><form class="modal-body" id="paysheetForm"><div class="paysheet-main-fields"><label><span>Employee</span><select name="employee_id" required>${employeeOptions}</select></label><label><span>Payroll month</span><input name="period_month" type="month" value="${new Date().toISOString().slice(0,7)}" required></label></div><div class="paysheet-adjustments"><section><header><b>Additions</b><small>Bonus, overtime, reimbursements</small></header>${adjustmentRows('addition',['Bonus','Overtime','Other addition'])}</section><section><header><b>Reductions</b><small>Loan, absence, advances</small></header>${adjustmentRows('deduction',['Loan / advance','Absence / no-pay','Other reduction'])}</section></div><label><span>Payroll note</span><textarea name="notes" rows="3" placeholder="Optional note shown in the employee payroll history"></textarea></label><div class="modal-actions"><button type="button" class="btn" data-close-modal>Cancel</button><button type="submit" class="btn primary">Save paysheet</button></div></form></section>`;layer.classList.add('open');layer.setAttribute('aria-hidden','false');$$('[data-close-modal]',layer).forEach(button=>button.onclick=closeModal);const form=$('#paysheetForm',layer);form.onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form));const lines=kind=>[0,1,2].map(index=>({label:String(values[`${kind}_label_${index}`]||'').trim(),amount:Number(values[`${kind}_amount_${index}`]||0)})).filter(item=>item.label&&item.amount>0);const button=$('[type="submit"]',form);button.disabled=true;button.textContent='Saving paysheet…';const result=await supabase.rpc('save_employee_paysheet',{p_org_id:currentOrg.id,p_period_month:`${values.period_month}-01`,p_employee_id:values.employee_id,p_additions:lines('addition'),p_deductions:lines('deduction'),p_notes:values.notes||null});if(result.error){button.disabled=false;button.textContent='Save paysheet';return toast(result.error.message)}closeModal();await loadWorkspaceData();render('people');toast('Employee paysheet saved to payroll history')};
}

