function openFormModal(title,eyebrow,fields,onSubmit,submitLabel='Save record'){
 const layer=$('#modalLayer');const tpl=$('#modalTemplate').content.cloneNode(true);layer.innerHTML='';layer.append(tpl);
 $('#modalTitle',layer).textContent=title;$('#modalEyebrow',layer).textContent=eyebrow;
 $('#modalBody',layer).innerHTML=`<form id="smartForm"><div class="field-grid">${fields.map(field=>`<div class="field ${field.full?'full':''}"><label>${field.label}${field.optional?' <small>(optional)</small>':''}</label>${field.type==='select'?`<select name="${field.name}" ${field.required===false?'':'required'}>${field.options.map(option=>`<option value="${escapeHtml(option.value??option)}" ${String(option.value??option)===String(field.value??'')?'selected':''}>${escapeHtml(option.label??option)}</option>`).join('')}</select>`:field.type==='textarea'?`<textarea name="${field.name}" rows="3" ${field.placeholder?`placeholder="${escapeHtml(field.placeholder)}"`:''} ${field.required===false?'':'required'}>${escapeHtml(field.value||'')}</textarea>`:`<input name="${field.name}" type="${field.type||'text'}" value="${escapeHtml(field.value??'')}" ${field.min!=null?`min="${field.min}"`:''} ${field.step?`step="${field.step}"`:''} ${field.placeholder?`placeholder="${escapeHtml(field.placeholder)}"`:''} ${field.required===false?'':'required'}>`}</div>`).join('')}</div><div class="modal-actions"><button type="button" class="btn" data-close-modal>Cancel</button><button class="btn primary" type="submit">${submitLabel}</button></div></form>`;
 hydrateIcons(layer);layer.classList.add('open');layer.setAttribute('aria-hidden','false');$$('[data-close-modal]',layer).forEach(x=>x.onclick=closeModal);
 const form=$('#smartForm',layer);form.onsubmit=async event=>{event.preventDefault();const button=$('[type="submit"]',form);button.disabled=true;button.textContent='Saving…';try{const success=await onSubmit(Object.fromEntries(new FormData(form)));if(success!==false)closeModal();else{button.disabled=false;button.textContent=submitLabel}}catch(error){toast(error.message||'Unable to save');button.disabled=false;button.textContent=submitLabel}};
 setTimeout(()=>$('.field input,.field select',layer)?.focus(),40);
}

