 layer.classList.add('open');layer.setAttribute('aria-hidden','false');hydrateIcons(layer);$$('[data-close-modal]',layer).forEach(x=>x.onclick=()=>{closeModal();render('pos')});$('[data-print-receipt]',layer).onclick=()=>printReceiptDocument(receipt,'receipt');$('[data-print-a4]',layer).onclick=()=>printReceiptDocument(receipt,'a4');
