function bindKanban(){
 let dragged=null;
 $$('.deal-card').forEach(card=>{card.ondragstart=()=>{dragged=card;card.classList.add('dragging')};card.ondragend=()=>card.classList.remove('dragging')});
 $$('.kanban-col').forEach(col=>{col.ondragover=e=>e.preventDefault();col.ondrop=async()=>{if(!dragged)return;col.appendChild(dragged);const deal=state.deals.find(d=>d.id==dragged.dataset.id);deal.stage=col.dataset.stage;const {error}=await supabase.from('opportunities').update({stage:deal.stage}).eq('id',deal.id);if(error)return toast(error.message);persist();toast(`Opportunity moved to ${deal.stage}`);render('sales')}})
}

function openCreate(){
 const moduleFields=activeApplication?.[0]==='Sales'?[['Customer','customer'],['Customer email','customer_email','email'],['Product SKU','product_sku'],['Description','description'],['Quantity','quantity','number'],['Unit price','unit_price','number'],['Tax rate %','tax_rate','number']]:[['Title','title'],['Reference','reference'],['Amount','amount','number'],['Due date','due_date','date'],['Details','details','textarea']];
 const configs={
  sales:{title:'New opportunity',fields:[['Company','company'],['Opportunity','title'],['Expected value','value','number'],['Probability %','prob','number']]},
  finance:{title:'New invoice',fields:[['Customer','customer'],['Amount','amount','number'],['Invoice date','date','date']]},
  inventory:{title:'New stock transfer',fields:[['Product','name'],['Quantity','stock','number'],['Destination warehouse','warehouse']]},
  manufacturing:{title:'New work order',fields:[['Product','product'],['Quantity','quantity','number'],['Work center','center']]},
  people:{title:'Add employee',fields:[['Full name','name'],['Job title','role'],['Department','dept']]},
  services:{title:'New project',fields:[['Project name','name'],['Client','client'],['Due date','due','date']]},
  marketing:{title:'New campaign',fields:[['Campaign name','name'],['Channel','channel'],['Audience','audience','number']]},
  commerce:{title:'New web page',fields:[['Page title','title'],['URL slug','slug'],['Page type','type']]},
  productivity:{title:'New note',fields:[['Title','title'],['Content','content','textarea']]},
  apps:{title:'Build custom app',fields:[['App name','name'],['Purpose','purpose','textarea']]},
  module:{title:activeApplication?.[0]==='Sales'?'New quotation':`New ${activeApplication?.[0]||'module'} record`,fields:moduleFields},
  settings:{title:'Save settings',fields:[]},overview:{title:'Quick create',fields:[['Record type','type'],['Title','title'],['Details','details','textarea']]}
 };
 const c=configs[currentRoute]||configs.overview;const layer=$('#modalLayer');const tpl=$('#modalTemplate').content.cloneNode(true);layer.innerHTML='';layer.append(tpl);$('#modalTitle',layer).textContent=c.title;$('#modalBody',layer).innerHTML=`<form id="createForm"><div class="field-grid">${c.fields.map(f=>`<div class="field ${f[2]==='textarea'?'full':''}"><label>${f[0]}</label>${f[2]==='textarea'?`<textarea name="${f[1]}" rows="4" required></textarea>`:`<input name="${f[1]}" type="${f[2]||'text'}" required>`}</div>`).join('')}</div><div class="modal-actions"><button type="button" class="btn" data-close-modal>Cancel</button><button class="btn primary" type="submit">Save record</button></div></form>`;hydrateIcons(layer);layer.classList.add('open');layer.setAttribute('aria-hidden','false');$$('[data-close-modal]',layer).forEach(x=>x.onclick=closeModal);const form=$('#createForm',layer);if(form)form.onsubmit=async e=>{e.preventDefault();const submit=$('[type="submit"]',form);submit.disabled=true;submit.textContent='Saving…';const saved=await saveRecord(new FormData(form));if(saved)closeModal();else{submit.disabled=false;submit.textContent='Save record'}};setTimeout(()=>$('.field input,.field textarea',layer)?.focus(),50);
}
async function saveRecord(fd){
 const o=Object.fromEntries(fd.entries());let result={data:null,error:null};
 if(!currentOrg?.id){toast('No active workspace');return false}
 if(currentRoute==='sales')result=await supabase.from('opportunities').insert({org_id:currentOrg.id,company:o.company,title:o.title,value:+o.value,probability:+o.prob,stage:'New',owner_id:session.user.id}).select().single();
 else if(currentRoute==='finance')result=await supabase.from('invoices').insert({org_id:currentOrg.id,number:`INV-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`,customer:o.customer,issue_date:o.date,subtotal:+o.amount,status:'Pending',created_by:session.user.id}).select().single();
 else if(currentRoute==='people')result=await supabase.from('employees').insert({org_id:currentOrg.id,name:o.name,role_title:o.role,department:o.dept,email:null}).select().single();
 else if(currentRoute==='services')result=await supabase.from('projects').insert({org_id:currentOrg.id,name:o.name,client:o.client,due_date:o.due,progress:0,status:'On track',manager_id:session.user.id}).select().single();
 else if(currentRoute==='marketing')result=await supabase.from('campaigns').insert({org_id:currentOrg.id,name:o.name,channel:o.channel,audience_size:+o.audience,created_by:session.user.id}).select().single();
 else if(currentRoute==='commerce')result=await supabase.from('website_pages').insert({org_id:currentOrg.id,title:o.title,slug:o.slug,page_type:o.type}).select().single();
 else if(currentRoute==='productivity')result=await supabase.from('knowledge_articles').insert({org_id:currentOrg.id,title:o.title,content:o.content,created_by:session.user.id}).select().single();
 else if(currentRoute==='module'&&activeApplication?.[0]==='Sales'){
   const product=state.products.find(p=>p.sku.toLowerCase()===String(o.product_sku||'').toLowerCase());
   const number=`SO-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`;
   const order=await supabase.from('sales_orders').insert({org_id:currentOrg.id,number,customer:o.customer,customer_email:o.customer_email||null,status:'draft',valid_until:new Date(Date.now()+14*86400000).toISOString().slice(0,10),salesperson_id:session.user.id}).select().single();
   if(order.error){result=order}else result=await supabase.from('sales_order_lines').insert({sales_order_id:order.data.id,product_id:product?.id||null,description:o.description||product?.name||o.product_sku,quantity:+o.quantity,unit_price:+o.unit_price,tax_rate:+o.tax_rate||0}).select().single();
 }
 else if(currentRoute==='module')result=await supabase.from('module_records').insert({org_id:currentOrg.id,module_key:moduleKey(activeApplication),title:o.title,reference:o.reference||null,amount:o.amount?+o.amount:null,due_date:o.due_date||null,data:{details:o.details||'',category:activeApplication?.[1]},created_by:session.user.id}).select().single();
 else {toast('This workflow is ready for configuration');return true}
 if(result.error){toast(result.error.message);return false}
 if(currentRoute==='module'){await openApplication(activeApplication)}else{await loadWorkspaceData();render()}toast(`${o.title||o.name||o.company||'Record'} created successfully`);return true;
}
function closeModal(){const l=$('#modalLayer');l.classList.remove('open');l.setAttribute('aria-hidden','true')}

function openSearch(){
 const all=Object.entries(appGroups).flatMap(([g,items])=>items.map(i=>({name:i,meta:g,route:({Sales:'sales',Finance:'finance',Operations:'inventory',People:'people',Marketing:'marketing',Services:'services',Productivity:'productivity',Website:'commerce'})[g]})));
 const layer=$('#modalLayer');layer.innerHTML='<div class="modal-backdrop" data-close-modal></div><section class="modal search-modal"><div class="modal-body"><input class="command-input" id="commandInput" placeholder="Search apps, customers, invoices, or actions…"><div class="search-results" id="searchResults"></div></div></section>';layer.classList.add('open');layer.setAttribute('aria-hidden','false');$('[data-close-modal]',layer).onclick=closeModal;const input=$('#commandInput');const results=$('#searchResults');const draw=()=>{const q=input.value.toLowerCase();const items=all.filter(x=>(x.name+' '+x.meta).toLowerCase().includes(q)).slice(0,8);results.innerHTML=items.map(x=>`<button class="search-result" data-go="${x.route}"><span class="app-icon">${x.name[0]}</span><span><strong>${x.name}</strong><small>${x.meta} · Open workspace</small></span></button>`).join('')||'<div class="empty-state">No results found</div>';$$('[data-go]',results).forEach(b=>b.onclick=()=>{closeModal();render(b.dataset.go)})};input.oninput=draw;draw();setTimeout(()=>input.focus(),40)
}
function openFocusedSearch(){
 const profile=activeBusinessProfile();const routes=[['home','Home','Command center','home'],['overview','ERP Overview','Cross-functional control','grid'],...profile.cards.map(c=>[c[0],c[1],c[2],c[3]]),['settings','Settings','Company and workspace configuration','settings']];
 const unique=[...new Map(routes.map(item=>[item[0],item])).values()];const layer=$('#modalLayer');layer.innerHTML='<div class="modal-backdrop" data-close-modal></div><section class="modal search-modal"><div class="modal-body"><input class="command-input" id="commandInput" placeholder="Search your workspace or an action…"><div class="search-results" id="searchResults"></div></div></section>';layer.classList.add('open');layer.setAttribute('aria-hidden','false');$('[data-close-modal]',layer).onclick=closeModal;const input=$('#commandInput');const results=$('#searchResults');const draw=()=>{const query=input.value.toLowerCase();const matches=unique.filter(item=>(item[1]+' '+item[2]).toLowerCase().includes(query));results.innerHTML=matches.map(item=>`<button class="search-result" data-go="${item[0]}"><span class="app-icon">${icon(item[3])}</span><span><strong>${item[1]}</strong><small>${item[2]}</small></span></button>`).join('')||'<div class="empty-state">No matching module or action</div>';hydrateIcons(results);$$('[data-go]',results).forEach(b=>b.onclick=()=>{closeModal();render(b.dataset.go)})};input.oninput=draw;draw();setTimeout(()=>input.focus(),40);
}
function toast(message){const el=document.createElement('div');el.className='toast';el.innerHTML=`<b>✓</b><span>${message}</span>`;$('#toastStack').append(el);setTimeout(()=>el.remove(),3000)}
function notificationPanel(){let p=$('.notification-panel');if(!p){p=document.createElement('div');p.className='notification-panel';document.body.append(p)}const unread=systemNotifications.filter(item=>!item.read);p.innerHTML=`<header><div><small>ACCOUNT MESSAGES</small><h3>Notifications</h3></div><span>${unread.length} unread</span></header><div class="notification-list">${systemNotifications.map(item=>`<button class="system-notice ${escapeHtml(item.severity)} ${item.read?'read':''}" data-notification-read="${item.id}"><i>${icon(item.severity==='critical'?'help':item.severity==='success'?'check':'message')}</i><span><b>${escapeHtml(item.title)}</b><p>${escapeHtml(item.body)}</p><small>${new Date(item.created_at).toLocaleString('en-LK',{dateStyle:'medium',timeStyle:'short'})}</small></span></button>`).join('')||'<div class="notification-empty"><b>You are all caught up</b><p>Important messages from the system administrator will appear here.</p></div>'}</div>`;hydrateIcons(p);$$('[data-notification-read]',p).forEach(button=>button.onclick=async()=>{const item=systemNotifications.find(entry=>entry.id===button.dataset.notificationRead);if(item&&!item.read){await supabase.rpc('mark_system_notification_read',{p_notification_id:item.id});item.read=true;button.classList.add('read');updateNotificationChrome()}});p.classList.toggle('open')}

function updateNotificationChrome(){const unread=systemNotifications.filter(item=>!item.read).length;const count=$('#notificationButton .status-count');if(count){count.textContent=unread;count.hidden=!unread}const dot=$('#notificationButton .status-dot');if(dot)dot.classList.toggle('urgent',systemNotifications.some(item=>!item.read&&['warning','critical'].includes(item.severity)))}

function workspaceMessageBanner(){const priority=systemNotifications.find(item=>!item.read&&item.severity==='critical')||systemNotifications.find(item=>!item.read&&item.severity==='warning');if(!priority&&workspaceGate?.billing_status!=='past_due')return '';const title=priority?.title||(workspaceGate?.billing_status==='past_due'?'Payment action required':'Important account notice');const body=priority?.body||'Your workspace payment is past due. Please contact the system administrator to avoid service interruption.';return `<section class="workspace-alert-banner ${priority?.severity||'warning'}"><span>${icon('help')}</span><div><small>SYSTEM ADMINISTRATOR NOTICE</small><b>${escapeHtml(title)}</b><p>${escapeHtml(body)}</p></div>${priority?`<button data-banner-read="${priority.id}">Mark as read</button>`:''}</section>`}

async function loadAccessControlData(){
 if(!isSuperAdmin()){accessAccounts=[];auditEntries=[];return}
 const [membershipsResult,accessResult,auditResult]=await Promise.all([
  supabase.from('memberships').select('*').eq('org_id',currentOrg.id).order('created_at'),
  supabase.from('organization_user_access').select('*,salon_locations(id,name,city,employee_login_slug)').eq('org_id',currentOrg.id),
  supabase.from('activity_log').select('*').eq('org_id',currentOrg.id).order('created_at',{ascending:false}).limit(100)
 ]);
 const failed=[membershipsResult,accessResult,auditResult].find(result=>result.error);if(failed)throw failed.error;
 const memberIds=(membershipsResult.data||[]).map(item=>item.user_id);const actorIds=(auditResult.data||[]).map(item=>item.actor_id).filter(Boolean);const profileIds=[...new Set([...memberIds,...actorIds])];
 const profilesResult=profileIds.length?await supabase.from('profiles').select('id,email,full_name,must_change_password,platform_role').in('id',profileIds):{data:[],error:null};if(profilesResult.error)throw profilesResult.error;
 const profileMap=new Map((profilesResult.data||[]).map(profile=>[profile.id,profile]));const accessMap=new Map((accessResult.data||[]).map(access=>[access.user_id,access]));
 accessAccounts=(membershipsResult.data||[]).map(membership=>{const profile=profileMap.get(membership.user_id)||{};const access=accessMap.get(membership.user_id);const fallback=['owner','admin','manager'].includes(membership.role)?accessTemplates.manager.permissions:accessTemplates.viewer.permissions;return {...membership,...profile,user_id:membership.user_id,title:access?.title||'',location_id:access?.location_id||null,salon_locations:access?.salon_locations||null,permissions:access?.permissions||fallback}});
 auditEntries=(auditResult.data||[]).map(entry=>({...entry,actor_name:profileMap.get(entry.actor_id)?.full_name||profileMap.get(entry.actor_id)?.email||'System'}));
}

