function updateChrome(){
  const workspaceName=currentOrg?.name||'Your workspace';
  const profile=activeBusinessProfile();
  $('.workspace-switcher strong').textContent=workspaceName;
  $('.workspace-switcher small').textContent=`${profile.short} · ${currentMembership?.role||'member'}`;
  const name=userProfile?.full_name||session?.user?.email?.split('@')[0]||'User';
  $('.user-copy strong').textContent=name;
  $('#sidebarAccount .sidebar-account-name').textContent=name;
  $('#sidebarAccount .sidebar-account-role').textContent=isSystemAdmin()?'System administrator':(currentMembership?.role||'Member');
  $('#sidebarAccount .sidebar-account-avatar').textContent=name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
  $('.user-copy small').textContent=isSystemAdmin()?'System administrator':userProfile?.platform_role==='super_admin'?'Workspace super admin':(currentMembership?.role||'Member');
  $('.user-avatar').textContent=name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
  $('.workspace-avatar').textContent=workspaceName.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();
  const enabled=new Set(Array.isArray(orgSettings?.enabled_modules)?orgSettings.enabled_modules:profile.modules);
  $$('.nav-item[data-module]').forEach(item=>item.classList.toggle('module-hidden',!enabled.has(item.dataset.module)));
  const industryNav=$('#industryModuleNav');if(industryNav){industryNav.classList.toggle('module-hidden',!profile.operation);industryNav.querySelector('span').textContent=profile.operation?.label||'Industry Operations';industryNav.setAttribute('aria-label',profile.operation?.label||'Industry Operations')}
  $$('.super-admin-nav').forEach(item=>item.classList.toggle('access-hidden',!isSuperAdmin()));
  $$('.system-admin-nav').forEach(item=>item.classList.toggle('access-hidden',!isSystemAdmin()));
  $$('.nav-item[data-route]').forEach(item=>item.classList.toggle('access-hidden',!routeAllowed(item.dataset.route)));
  const posLabel=$('.nav-item[data-route="pos"] span');if(posLabel)posLabel.textContent=profile===businessProfiles.pharmacy?'Pharmacy POS':profile===businessProfiles.salon?'Client Checkout':profile===businessProfiles.retail_grocery?'Grocery POS':profile===businessProfiles.restaurant?'Restaurant POS':profile===businessProfiles.clothing_fashion?'Fashion POS':profile===businessProfiles.healthcare_clinic?'Clinic Billing':'Point of Sale';
  if(!$('.sync-pill')){const sync=document.createElement('div');sync.className='sync-pill';sync.textContent='Synced with Supabase';document.body.append(sync)}
}

function routeAllowed(route){
 if(route==='home')return true;
 if(route==='system_admin')return isSystemAdmin();
 if(route==='access_control')return isSuperAdmin();
 const industryPermission=currentOrg?.business_type==='hotel'?'hotel_view':currentOrg?.business_type==='healthcare_clinic'?'medical_view':'salon_view';
 const permissionByRoute={overview:'salon_view',industry_ops:industryPermission,salon:'salon_view',service_catalog:'salon_view',reminders:'salon_view',people:'salon_view',customers:'customers_view',pos:'sales_view',sales_history:'sales_view',inventory:'sales_view',settings:'settings_view'};
 if(currentAccess&&(!permissionByRoute[route]||!hasPermission(permissionByRoute[route])))return false;
 const enabled=Array.isArray(orgSettings?.enabled_modules)?orgSettings.enabled_modules:activeBusinessProfile().modules;
 return route==='settings'||enabled.includes(route);
}

async function saveOrgSettings(){
  const orgPatch={};$$('[data-org-field]',page).forEach(el=>orgPatch[el.dataset.orgField]=el.value.trim());
  const settingsPatch={};$$('[data-setting-field]',page).forEach(el=>settingsPatch[el.dataset.settingField]=el.value);
  const preferencePatch={};$$('[data-preference-field]',page).forEach(el=>preferencePatch[el.dataset.preferenceField]=el.type==='number'||el.dataset.preferenceType==='number'||el.dataset.preferenceField==='booking_interval'?Number(el.value):el.value);$$('[data-preference-check]',page).forEach(el=>preferencePatch[el.dataset.preferenceCheck]=el.checked);if(Object.keys(preferencePatch).length){if(preferencePatch.opening_time&&preferencePatch.closing_time&&preferencePatch.opening_time>=preferencePatch.closing_time)return toast('Closing time must be after opening time');settingsPatch.preferences={...(orgSettings?.preferences||{}),...preferencePatch}}
  if(orgPatch.business_type){orgPatch.industry=orgPatch.business_type;settingsPatch.enabled_modules=(businessProfiles[orgPatch.business_type]||businessProfiles.general_erp).modules}
  const [orgResult,settingsResult]=await Promise.all([
    supabase.from('organizations').update(orgPatch).eq('id',currentOrg.id).select().single(),
    supabase.from('organization_settings').update(settingsPatch).eq('org_id',currentOrg.id).select().single()
  ]);
  if(orgResult.error||settingsResult.error)return toast((orgResult.error||settingsResult.error).message);
  currentOrg=orgResult.data;orgSettings=settingsResult.data;await loadIndustryModuleRecords();updateChrome();subscribeSalonRealtime();render('settings');toast('Workspace settings saved');
}

function openPrintableDocument(title,body,{pageSize='A4',styles=''}={}){
 const popup=window.open('','_blank');if(!popup){toast('Allow pop-ups to open the printable document');return}popup.opener=null;popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${escapeHtml(title)}</title><meta name="viewport" content="width=device-width,initial-scale=1"><style>@page{size:${pageSize};margin:${pageSize==='A4'?'14mm':'4mm'}}*{box-sizing:border-box}body{margin:0;color:#172033;background:#fff;font-family:Arial,sans-serif;-webkit-print-color-adjust:exact;print-color-adjust:exact}${styles}</style></head><body>${body}<script>window.addEventListener('load',()=>setTimeout(()=>window.print(),200))<\/script></body></html>`);popup.document.close();
}

function saveClientBooking(record){
 let bookings=[];try{bookings=JSON.parse(localStorage.getItem('hich-salon-bookings')||'[]')}catch{}bookings=[record,...bookings.filter(item=>item.appointment_id!==record.appointment_id)].slice(0,25);localStorage.setItem('hich-salon-bookings',JSON.stringify(bookings));
}

function bookingMessage(record){return `Appointment confirmed\nSalon: ${record.salon}\nLocation: ${record.location||'Main location'}\nService: ${record.service}\nDate & time: ${new Date(record.starts_at).toLocaleString('en-LK',{dateStyle:'full',timeStyle:'short'})}\nCustomer: ${record.customer_name}\nPhone: ${record.customer_phone}${record.staff?`\nSpecialist: ${record.staff}`:''}${Number(record.price)>0?`\nPrice: ${lkr(record.price)}`:''}\nBooking ID: ${record.appointment_id}`}

function printBookingConfirmation(record){
 const rows=[['Booking ID',record.appointment_id],['Customer',record.customer_name],['Phone',record.customer_phone],['Location',record.location||'Main location'],['Service',record.service],['Date & time',new Date(record.starts_at).toLocaleString('en-LK',{dateStyle:'full',timeStyle:'short'})],['Ends',new Date(record.ends_at).toLocaleTimeString('en-LK',{hour:'numeric',minute:'2-digit'})],['Specialist',record.staff||'To be assigned'],['Price',Number(record.price)>0?lkr(record.price):'Price on request']];const body=`<main class="booking-pdf"><header><div class="mark">H</div><div><small>APPOINTMENT CONFIRMATION</small><h1>${escapeHtml(record.salon)}</h1><p>${escapeHtml(record.location||'')} · ${escapeHtml(record.salon_address||'')}</p></div><b>CONFIRMED</b></header><section><h2>${escapeHtml(record.service)}</h2><p>${new Date(record.starts_at).toLocaleString('en-LK',{dateStyle:'full',timeStyle:'short'})}</p></section><table>${rows.map(([label,value])=>`<tr><th>${escapeHtml(label)}</th><td>${escapeHtml(value)}</td></tr>`).join('')}</table><footer>Please keep this confirmation and contact ${escapeHtml(record.salon_phone||record.salon)} if you need to change your appointment.</footer></main>`;openPrintableDocument(`Booking ${record.appointment_id}`,body,{styles:'.booking-pdf{max-width:180mm;margin:auto;padding:10mm;border:1px solid #e3dcea}.booking-pdf header{display:grid;grid-template-columns:48px 1fr auto;gap:16px;align-items:center;border-bottom:3px solid #654485;padding-bottom:18px}.mark{width:48px;height:48px;border-radius:13px;background:#654485;color:#fff;display:grid;place-items:center;font-size:25px;font-weight:900}.booking-pdf small{color:#654485;font-weight:800;letter-spacing:.1em}.booking-pdf h1{font-size:24px;margin:5px 0}.booking-pdf p{color:#687086;margin:0}.booking-pdf header>b{color:#18745e;background:#eaf7f2;border-radius:20px;padding:8px 12px;font-size:11px}.booking-pdf section{background:#f6f2f9;padding:20px;margin:22px 0}.booking-pdf section h2{margin:0 0 8px;font-size:20px}.booking-pdf table{width:100%;border-collapse:collapse}.booking-pdf th,.booking-pdf td{padding:11px 8px;border-bottom:1px solid #e7e8ed;text-align:left;font-size:13px}.booking-pdf th{width:34%;color:#6f7688}.booking-pdf footer{margin-top:28px;padding-top:15px;border-top:1px solid #dfe1e7;color:#72798a;font-size:12px;line-height:1.6}'});
}

function showPublicBookingConfirmation(booking,appointment,values){
 const record={...appointment,customer_name:values.customer_name.trim(),customer_phone:values.customer_phone.trim(),customer_email:values.customer_email||'',notes:values.notes||'',saved_at:new Date().toISOString()};saveClientBooking(record);const message=bookingMessage(record);const phone=String(record.salon_phone||'').replace(/\D/g,'').replace(/^0/,'94');booking.innerHTML=`<div class="booking-confirmed"><span>${icon('check')}</span><small>Appointment confirmed & saved</small><h1>You’re booked at ${escapeHtml(record.salon)}</h1><p>${escapeHtml(record.service)} at ${escapeHtml(record.location||'the selected location')} on ${new Date(record.starts_at).toLocaleString('en-LK',{dateStyle:'full',timeStyle:'short'})}</p><div class="booking-confirmation-card"><dl><div><dt>Customer</dt><dd>${escapeHtml(record.customer_name)}</dd></div><div><dt>Phone</dt><dd>${escapeHtml(record.customer_phone)}</dd></div><div><dt>Location</dt><dd>${escapeHtml(record.location||'Main location')}</dd></div><div><dt>Service</dt><dd>${escapeHtml(record.service)}</dd></div><div><dt>Specialist</dt><dd>${escapeHtml(record.staff||'To be assigned')}</dd></div><div><dt>Booking ID</dt><dd>${escapeHtml(record.appointment_id)}</dd></div></dl><p>This complete booking has been saved on this device.</p><div class="booking-confirmation-actions"><button data-booking-pdf>${icon('download')} Save PDF</button><button class="whatsapp" data-booking-whatsapp>${icon('message')} Send on WhatsApp</button><button class="secondary" data-book-another>Book another</button></div></div></div>`;hydrateIcons(booking);$('[data-booking-pdf]',booking).onclick=()=>printBookingConfirmation(record);$('[data-booking-whatsapp]',booking).onclick=()=>window.open(`https://wa.me/${phone}?text=${encodeURIComponent(message)}`,'_blank','noopener');$('[data-book-another]',booking).onclick=()=>location.reload();
}

