 const patientUrl=`${publicUrl('medical',slug)}?source=qr`;const qr=await QRCode.toDataURL(patientUrl,{width:520,margin:2,color:{dark:'#071c2b',light:'#ffffff'}});let centerId='';let refreshBusy=false;
 const renderMonitor=data=>{const sessions=data.sessions||[];centerId=data.center.id;const active=sessions.filter(item=>['called','in_consultation'].includes(item.current_status)).length;portal.innerHTML=`<main class="medical-monitor-shell"><header class="monitor-header"><a class="monitor-brand" href="/"><span class="brand-mark"><i></i><i></i><i></i></span><b>HICH ONE</b></a><div><span class="monitor-live" data-realtime-state><i></i> LIVE</span><time data-monitor-clock></time></div></header><section class="monitor-title"><div><span>WELCOME TO</span><h1>${escapeHtml(data.center.name)}</h1><p>${escapeHtml(data.center.address||'Please watch the screen for your number')}</p></div><aside><b>${sessions.length}</b><span>doctors today</span><b>${active}</b><span>now serving</span></aside></section><section class="monitor-doctor-grid">${sessions.map(item=>`<article class="monitor-doctor ${item.current_number?'serving':'ready'}"><header><span>${escapeHtml(item.queue_prefix)}</span><div><h2>${escapeHtml(item.doctor_name)}</h2><p>${escapeHtml(item.specialty||'General practice')} · ${escapeHtml(item.room_label||'Room to be announced')}</p></div><em>${escapeHtml(item.session_status)}</em></header><div class="monitor-number"><small>${item.current_number?'NOW SERVING':'QUEUE STATUS'}</small><strong>${escapeHtml(item.current_number||'READY')}</strong><span>${item.current_status==='in_consultation'?'In consultation':item.current_number?'Please proceed to the consultation room':'Waiting for the next call'}</span></div><footer><span><b>${item.waiting_count}</b> waiting</span><span><b>${item.completed_count}</b> completed</span><span><b>${String(item.starts_at).slice(0,5)}</b> starts</span></footer></article>`).join('')||'<div class="monitor-empty"><h2>No doctor sessions are scheduled today</h2><p>Please speak with reception for assistance.</p></div>'}</section><aside class="monitor-join-card"><img src="${qr}" alt="QR code to get a patient number"><div><span>NEED A NUMBER?</span><h2>Scan to join the queue</h2><p>Choose your doctor, enter your name, and keep your live number on your phone.</p><small>${escapeHtml(patientUrl)}</small></div></aside><footer class="monitor-footer"><span>Queue information updates automatically</span><b>Powered by HICH ONE</b><span>This screen does not display patient names</span></footer></main>`;hydrateIcons(portal);const clock=$('[data-monitor-clock]',portal);const updateClock=()=>{if(clock)clock.textContent=new Date().toLocaleString('en-LK',{weekday:'short',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',second:'2-digit'})};updateClock();clearInterval(portal._clockTimer);portal._clockTimer=setInterval(updateClock,1000)};
 const refresh=async()=>{if(refreshBusy)return;refreshBusy=true;const result=await supabase.rpc('get_public_medical_monitor',{p_slug:slug});refreshBusy=false;if(result.error){portal.innerHTML=`<div class="booking-unavailable"><h1>Monitor unavailable</h1><p>${escapeHtml(result.error.message)}</p><a href="/">Return to HICH ONE</a></div>`;return false}renderMonitor(result.data);return true};
 if(!await refresh())return;
