function showAuthError(message,{resend=false,info=false}={}){const box=$('#authError');box.textContent=message;box.classList.toggle('hidden',!message);box.classList.toggle('info',info);$('#resendConfirmation').classList.toggle('hidden',!resend)}
function authRedirectUrl(){return `${location.origin}/`}
function readAuthCallbackError(){
  const params=new URLSearchParams(location.hash.replace(/^#/,''));
  const code=params.get('error_code');
  if(!code)return null;
  const description=(params.get('error_description')||'Authentication failed.').replace(/\+/g,' ');
  history.replaceState(null,'',location.pathname+location.search);
  return {code,description};
}
function openRequiredPasswordChange(){
 const layer=$('#modalLayer');layer.innerHTML=`<div class="modal-backdrop locked"></div><section class="modal required-password-modal"><div class="modal-body"><span class="security-mark">${icon('check')}</span><span class="eyebrow">First sign-in security</span><h2>Create your private password</h2><p>Your temporary password worked. Replace it now before accessing workspace information.</p><form id="requiredPasswordForm"><label><span>New password</span><input name="password" type="password" minlength="10" autocomplete="new-password" required></label><label><span>Confirm new password</span><input name="confirm_password" type="password" minlength="10" autocomplete="new-password" required></label><small>Use at least 10 characters. Avoid reusing a password from another service.</small><button class="btn primary" type="submit">Secure my account</button></form></div></section>`;layer.classList.add('open');layer.setAttribute('aria-hidden','false');hydrateIcons(layer);const form=$('#requiredPasswordForm',layer);form.onsubmit=async event=>{event.preventDefault();const password=form.elements.password.value;if(password!==form.elements.confirm_password.value)return toast('The two passwords do not match');const submit=$('[type="submit"]',form);submit.disabled=true;submit.textContent='Securing account…';const updated=await supabase.auth.updateUser({password});if(updated.error){submit.disabled=false;submit.textContent='Secure my account';return toast(updated.error.message)}const profileUpdate=await supabase.from('profiles').update({must_change_password:false}).eq('id',session.user.id);if(profileUpdate.error){submit.disabled=false;submit.textContent='Secure my account';return toast(profileUpdate.error.message)}await supabase.from('activity_log').insert({org_id:currentOrg.id,actor_id:session.user.id,action:'account.password_changed',entity_type:'account',entity_id:session.user.id,metadata:{first_sign_in:true}});userProfile.must_change_password=false;closeModal();render('home');toast('Your private password is active')};
}
async function bootstrapApp(activeSession,employeePortalSlug=''){
  const portalSlug=employeePortalSlug||activeEmployeePortalSlug;if(bootstrapPromise)return bootstrapPromise;session=activeSession;if(portalSlug)activeEmployeePortalSlug=portalSlug;
  bootstrapPromise=(async()=>{
   $('#marketingSite').classList.add('hidden');$('#employeePortal')?.classList.add('hidden');$('#workspaceSuspended')?.classList.add('hidden');$('#authShell').classList.remove('hidden');$('#authLoading').classList.remove('hidden');$('#authForms').classList.add('hidden');let lastError;
   for(let attempt=0;attempt<2;attempt++){try{await loadWorkspaceData();lastError=null;break}catch(error){lastError=error;if(error.code==='WORKSPACE_SUSPENDED')break;if(attempt===0)await new Promise(resolve=>setTimeout(resolve,350))}}if(lastError)throw lastError;
   const expectedSlug=currentAccess?.salon_locations?.employee_login_slug||'';
   if(portalSlug){const validation=await supabase.rpc('validate_employee_login_portal',{p_slug:portalSlug});if(validation.error)throw validation.error;if(!isSuperAdmin()&&expectedSlug&&expectedSlug!==portalSlug)throw new Error('This account belongs to another business location. Use the permanent link provided by your administrator.');activeSalonLocationId=validation.data.location_id}
   else activeEmployeePortalSlug='';
   $('#marketingSite').classList.add('hidden');$('#authShell').classList.add('hidden');$('#employeePortal')?.classList.add('hidden');$('#workspaceSuspended')?.classList.add('hidden');$('#appShell').classList.remove('hidden');hydrateIcons();subscribeSalonRealtime();
   if(userProfile?.must_change_password){$('#appShell').classList.remove('onboarding-active');render('home');openRequiredPasswordChange();return}if(!orgSettings?.preferences?.onboarding_completed){showOnboarding();return}$('#appShell').classList.remove('onboarding-active');const initial=location.hash.slice(1);const defaultRoute=isSystemAdmin()?'system_admin':'home';render(renderers[initial]&&routeAllowed(initial)?initial:defaultRoute)
  })().catch(async error=>{if(error.code==='WORKSPACE_SUSPENDED'){showWorkspaceSuspended(error.gate);return}const failedPortal=portalSlug||activeEmployeePortalSlug;if(failedPortal){if(session)await supabase.auth.signOut({scope:'local'});session=null;await showEmployeePortal(failedPortal,error.message||'This account cannot use this location link.')}else{showAuth();showAuthError(error.message||'Unable to load your workspace.')}}).finally(()=>{bootstrapPromise=null});return bootstrapPromise;
}
function subscribeSalonRealtime(){
 if(salonRealtimeChannel){supabase.removeChannel(salonRealtimeChannel);salonRealtimeChannel=null}
 if(operationsRealtimeChannel){supabase.removeChannel(operationsRealtimeChannel);operationsRealtimeChannel=null}
 if(!currentOrg?.id)return;
 const refresh=()=>setTimeout(async()=>{if(!session)return;try{await loadWorkspaceData();if(currentRoute==='industry_ops')render('industry_ops')}catch{}},120);
 if(currentOrg.business_type==='hotel'){operationsRealtimeChannel=supabase.channel(`hotel-workspace-${currentOrg.id}`).on('postgres_changes',{event:'*',schema:'public',table:'hotel_bookings',filter:`org_id=eq.${currentOrg.id}`},refresh).on('postgres_changes',{event:'*',schema:'public',table:'hotel_room_types',filter:`org_id=eq.${currentOrg.id}`},refresh).subscribe();return}
 if(currentOrg.business_type==='healthcare_clinic'){operationsRealtimeChannel=supabase.channel(`medical-workspace-${currentOrg.id}`).on('postgres_changes',{event:'*',schema:'public',table:'medical_queue_tickets',filter:`org_id=eq.${currentOrg.id}`},refresh).on('postgres_changes',{event:'*',schema:'public',table:'medical_sessions',filter:`org_id=eq.${currentOrg.id}`},refresh).subscribe();return}
 if(activeBusinessProfile()!==businessProfiles.salon)return;
 salonRealtimeChannel=supabase.channel(`salon-workspace-${currentOrg.id}`).on('postgres_changes',{event:'*',schema:'public',table:'salon_appointments',filter:`org_id=eq.${currentOrg.id}`},()=>{setTimeout(async()=>{if(!session)return;try{await loadWorkspaceData();if(['salon','reminders'].includes(currentRoute))render(currentRoute);else toast('A salon booking was updated in real time')}catch{}},120)}).on('postgres_changes',{event:'*',schema:'public',table:'salon_unavailability',filter:`org_id=eq.${currentOrg.id}`},()=>{setTimeout(async()=>{if(!session)return;try{await loadWorkspaceData();if(['salon','settings'].includes(currentRoute))render(currentRoute)}catch{}},120)}).subscribe();
}
async function initAuth(){
  const hotelMatch=location.pathname.match(/^\/hotel\/([^/]+)\/?$/);if(hotelMatch){await showPublicHotel(decodeURIComponent(hotelMatch[1]));return}
  const medicalMonitorMatch=location.pathname.match(/^\/medical\/([^/]+)\/monitor\/?$/);if(medicalMonitorMatch){await showMedicalMonitor(decodeURIComponent(medicalMonitorMatch[1]));return}
  const doctorPortalMatch=location.pathname.match(/^\/doctor\/([0-9a-f-]{36})\/?$/i);if(doctorPortalMatch){await showDoctorPortal(doctorPortalMatch[1]);return}
  const medicalMatch=location.pathname.match(/^\/medical\/([^/]+)\/?$/);if(medicalMatch){await showPublicMedical(decodeURIComponent(medicalMatch[1]));return}
  const bookingMatch=location.pathname.match(/^\/book\/([^/]+)\/?$/);if(bookingMatch){await showPublicBooking(decodeURIComponent(bookingMatch[1]));return}
  const employeeMatch=location.pathname.match(/^\/staff\/([^/]+)\/?$/);const employeeSlug=employeeMatch?decodeURIComponent(employeeMatch[1]):'';if(employeeSlug)activeEmployeePortalSlug=employeeSlug;
  const forceAdminLogin=!employeeSlug&&new URLSearchParams(location.search).get('login')==='admin';
  const callbackError=readAuthCallbackError();
  const {data,error}=await supabase.auth.getSession();
  if(error){showAuth();showAuthError(error.message);return}
  session=data.session;
  const requested=location.hash.slice(1);
  if(forceAdminLogin){let existingAdmin=false;if(data.session){const role=await supabase.from('profiles').select('platform_role').eq('id',data.session.user.id).maybeSingle();existingAdmin=['super_admin','system_admin'].includes(role.data?.platform_role)}history.replaceState(null,'','/');if(existingAdmin)await bootstrapApp(data.session);else{if(data.session)await supabase.auth.signOut({scope:'local'});session=null;showAuth('signin')}}else if(employeeSlug){if(data.session)await bootstrapApp(data.session,employeeSlug);else await showEmployeePortal(employeeSlug)}else if(requested==='login'||requested==='signin')showAuth('signin');else if(requested==='signup')showAuth('signup');else if(data.session)await bootstrapApp(data.session);else showMarketing();
  if(callbackError){showAuth('signin');showAuthError(callbackError.description)}
  supabase.auth.onAuthStateChange((event,nextSession)=>{if(event==='SIGNED_OUT'){session=null;if(salonRealtimeChannel){supabase.removeChannel(salonRealtimeChannel);salonRealtimeChannel=null}if(operationsRealtimeChannel){supabase.removeChannel(operationsRealtimeChannel);operationsRealtimeChannel=null}const match=location.pathname.match(/^\/staff\/([^/]+)\/?$/);if(match)setTimeout(()=>showEmployeePortal(decodeURIComponent(match[1])),0);else showMarketing();return}if(nextSession)session=nextSession;if(event==='SIGNED_IN'&&nextSession&&$('#appShell').classList.contains('hidden')&&!['signin','signup','login'].includes(location.hash.slice(1))){const match=location.pathname.match(/^\/staff\/([^/]+)\/?$/);setTimeout(()=>bootstrapApp(nextSession,match?decodeURIComponent(match[1]):''),0)}});
}
